    ('190fdea4-2036-47fa-a6ca-81b3b0ab2e93'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:190fdea4-2036-47fa-a6ca-81b3b0ab2e93:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Roman Dam of Fonte Coberta', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('190fdea4-2036-47fa-a6ca-81b3b0ab2e93'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s002-rollback:190fdea4-2036-47fa-a6ca-81b3b0ab2e93:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Roman Dam of Fonte Coberta', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0119)", "decision": "clear", "status": "MISSING", "reasoning": "The register, the Portal do Arqueólogo and Wikipedia date the dam only as Roman (''época romana'', ''Romanization of Hispania''); no source gives a year or century for its construction, so there are not two dated sources.", "value_page": null}]'::jsonb),
    ('1941620d-0f59-46a3-9e13-d10e9c05cdfa'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1941620d-0f59-46a3-9e13-d10e9c05cdfa:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1000 - 1500 AD'' restored on Cheqollo', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1941620d-0f59-46a3-9e13-d10e9c05cdfa'::uuid, 'period_start', NULL, '1400', 'fields-wd1-2026-09-26b-s002-rollback:1941620d-0f59-46a3-9e13-d10e9c05cdfa:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1400'' restored on Cheqollo', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "clear", "status": "MISSING", "reasoning": "Only the MINCETUR inventory entry (turismoperuano.com) dates the site, placing its Inca funerary contexts ''alrededor de 1400 d.C. hasta 1532 d.C.'', while Spanish Wikipedia''s infobox assigns it to the Wari culture without a source; with a single source and a conflicting attribution there are not two independent dates, so the field is emptied.", "value_page": null}]'::jsonb),
    ('1941620d-0f59-46a3-9e13-d10e9c05cdfa'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:1941620d-0f59-46a3-9e13-d10e9c05cdfa:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Cheqollo', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "clear", "status": "MISSING", "reasoning": "The MINCETUR inventory calls Cheqollo ''un asentamiento humano'' with rectangular enclosures around a main plaza and burials inside the rooms, but English Wikipedia and Spanish Wikipedia say only ''archaeological site'' and no page found states a type word in English, so the stored settlement type cannot be quoted as required and the field is emptied for the owner.", "value_page": null}]'::jsonb),
    ('1986f645-dc61-4118-91b1-5138b582b77c'::uuid, 'geom', 'SRID=4326;POINT(-89.27306 17.31194)', '0101000020E6100000163996E6E34E56C01E8738EBD84C3140', 'fields-wd1-2026-09-26b-s002-rollback:1986f645-dc61-4118-91b1-5138b582b77c:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E6100000163996E6E34E56C01E8738EBD84C3140'' restored on Holmul', '[{"source": "https://www.geonames.org/3595457/holmul.html", "url": "https://www.geonames.org/3595457/holmul.html", "quote": "17.31194, -89.27306", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=34582", "url": "https://www.megalithic.co.uk/article.php?sid=34582", "quote": "Latitude: 17.311930N Longitude: 89.27393W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Holmul Archaeological Project''s 2000 report (Estrada-Belli, bu.edu/holmul) fixes the site centre by GPS on Building D of Group I, the tallest structure of the Main Plaza, at 17°18''43\"N 89°16''23\"W, and notes that the older published location lies about 2 km south-east of the actual site; GeoNames (17.31194, -89.27306) and the Megalithic Portal (17.31193, -89.27393) agree with it within 0.1 km. The stored point, like Wikipedia''s 17.300, -89.256, lies 2-4.5 km south-east, so it is replaced.", "value_page": null}]'::jsonb),
    ('1986f645-dc61-4118-91b1-5138b582b77c'::uuid, 'lat', '17.31194', '17.300184918690427', 'fields-wd1-2026-09-26b-s002-rollback:1986f645-dc61-4118-91b1-5138b582b77c:lat', 'rollback of fields-wd1-2026-09-26b-s002: lat ''17.300184918690427'' restored on Holmul', '[{"source": "https://www.geonames.org/3595457/holmul.html", "url": "https://www.geonames.org/3595457/holmul.html", "quote": "17.31194, -89.27306", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=34582", "url": "https://www.megalithic.co.uk/article.php?sid=34582", "quote": "Latitude: 17.311930N Longitude: 89.27393W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Holmul Archaeological Project''s 2000 report (Estrada-Belli, bu.edu/holmul) fixes the site centre by GPS on Building D of Group I, the tallest structure of the Main Plaza, at 17°18''43\"N 89°16''23\"W, and notes that the older published location lies about 2 km south-east of the actual site; GeoNames (17.31194, -89.27306) and the Megalithic Portal (17.31193, -89.27393) agree with it within 0.1 km. The stored point, like Wikipedia''s 17.300, -89.256, lies 2-4.5 km south-east, so it is replaced.", "value_page": null}]'::jsonb),
    ('1986f645-dc61-4118-91b1-5138b582b77c'::uuid, 'lon', '-89.27306', '-89.232659956648', 'fields-wd1-2026-09-26b-s002-rollback:1986f645-dc61-4118-91b1-5138b582b77c:lon', 'rollback of fields-wd1-2026-09-26b-s002: lon ''-89.232659956648'' restored on Holmul', '[{"source": "https://www.geonames.org/3595457/holmul.html", "url": "https://www.geonames.org/3595457/holmul.html", "quote": "17.31194, -89.27306", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=34582", "url": "https://www.megalithic.co.uk/article.php?sid=34582", "quote": "Latitude: 17.311930N Longitude: 89.27393W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0075)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Holmul Archaeological Project''s 2000 report (Estrada-Belli, bu.edu/holmul) fixes the site centre by GPS on Building D of Group I, the tallest structure of the Main Plaza, at 17°18''43\"N 89°16''23\"W, and notes that the older published location lies about 2 km south-east of the actual site; GeoNames (17.31194, -89.27306) and the Megalithic Portal (17.31193, -89.27393) agree with it within 0.1 km. The stored point, like Wikipedia''s 17.300, -89.256, lies 2-4.5 km south-east, so it is replaced.", "value_page": null}]'::jsonb),
    ('19aa5815-9965-43b3-a2d9-e35190fd50ec'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:19aa5815-9965-43b3-a2d9-e35190fd50ec:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Gran Saposoa', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(601) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('19aa5815-9965-43b3-a2d9-e35190fd50ec'::uuid, 'period_start', '601', '1', 'fields-wd1-2026-09-26b-s002-rollback:19aa5815-9965-43b3-a2d9-e35190fd50ec:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Gran Saposoa', '[{"source": "https://www.nbcnews.com/id/wbna9233051", "url": "https://www.nbcnews.com/id/wbna9233051", "quote": "Sean Savoy, 32, urged the government to take steps to protect the city, which he estimated housed 20,000 people and had hundreds of circular stone buildings in the 7th century.", "outcome": "found"}, {"source": "https://andina.pe/agencia/noticia-pondran-valor-complejo-arqueologico-gran-saposoa-san-martin-276155.aspx", "url": "https://andina.pe/agencia/noticia-pondran-valor-complejo-arqueologico-gran-saposoa-san-martin-276155.aspx", "quote": "Según estudios, el Gran Saposoa habría sido edificado entre los siglos VII y VIII", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0108)", "decision": "replace", "status": "MISSING", "reasoning": "The Associated Press report (NBC News) and Peru''s state news agency Andina both date the building of Gran Saposoa to the 7th (to 8th) century AD, i.e. year 601 in the 500-1000 AD bucket; the stored year 1 (1-500 AD bucket) has no support.", "value_page": null}]'::jsonb),
    ('19bf579e-21fe-47f0-80b0-20e1fa747a8b'::uuid, 'period_name', '500 BC - 1 AD', '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:19bf579e-21fe-47f0-80b0-20e1fa747a8b:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on Hillsborough, Devon', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-300) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('19bf579e-21fe-47f0-80b0-20e1fa747a8b'::uuid, 'period_start', '-300', '-1000', 'fields-wd1-2026-09-26b-s002-rollback:19bf579e-21fe-47f0-80b0-20e1fa747a8b:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1000'' restored on Hillsborough, Devon', '[{"source": "https://www.visitilfracombe.co.uk/blog/hillsborough-hillfort-ilfracombe/", "url": "https://www.visitilfracombe.co.uk/blog/hillsborough-hillfort-ilfracombe/", "quote": "Archaeologists believe Hillsborough was built during the Iron Age (around 300 BC), but its exact purpose remains a mystery.", "outcome": "found"}, {"source": "https://johnhmoore.co.uk/hele/hillsborough.htm", "url": "https://johnhmoore.co.uk/hele/hillsborough.htm", "quote": "suggested that Hillsborough was similarly occupied between c300 BC and c50 AD", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "MISSING", "reasoning": "Visit Ilfracombe says the fort was built around 300 BC and John Moore''s Hele history reports the Ilfracombe Museum curator''s dating of its occupation to c. 300 BC - c. 50 AD (the fort is unexcavated and dated by comparison with Embury Beacon); no source supports the stored c. 1000 BC, so the start is replaced by c. 300 BC in the 500 BC - 1 AD bucket.", "value_page": null}]'::jsonb),
    ('19bf579e-21fe-47f0-80b0-20e1fa747a8b'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:19bf579e-21fe-47f0-80b0-20e1fa747a8b:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Hillsborough, Devon', '[{"source": "https://en.wikipedia.org/wiki/Hillsborough,_Devon", "url": "https://en.wikipedia.org/wiki/Hillsborough,_Devon", "quote": "Hillsborough is the site of an Iron Age hill fort atop the cliff on a promontory at approx 115 metres above sea level.", "outcome": "found"}, {"source": "https://ukhillfortlidar.myportfolio.com/hillsborough-ilfracombe", "url": "https://ukhillfortlidar.myportfolio.com/hillsborough-ilfracombe", "quote": "Just as you leave Ilfracombe to the east along the A399 you will pass the large promontory fort, Hillsborough at Hele Bay.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the UK Hillfort Lidar page both describe Hillsborough as an Iron Age promontory hill fort cut off by ramparts; the most specific canonical type for it is Fort, not fortress/citadel.", "value_page": null}]'::jsonb),
    ('19bf579e-21fe-47f0-80b0-20e1fa747a8b'::uuid, 'source_url', 'https://www.northdevoncoast-nl.org.uk/coastalheritage/hillsborough-hillfort', 'https://en.wikipedia.org/wiki/Hillsborough,_Devon', 'fields-wd1-2026-09-26b-s002-rollback:19bf579e-21fe-47f0-80b0-20e1fa747a8b:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Hillsborough,_Devon'' restored on Hillsborough, Devon', '[{"source": "https://www.northdevoncoast-nl.org.uk/coastalheritage/hillsborough-hillfort", "url": "https://www.northdevoncoast-nl.org.uk/coastalheritage/hillsborough-hillfort", "quote": "Hillsborough is the second largest hillfort in North Devon.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=20353", "url": "https://www.megalithic.co.uk/article.php?sid=20353", "quote": "Site Name: Hillsborough Country: England County: Devon Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Wikipedia article on the local nature reserve; the hillfort has no Wikipedia article of its own, so the North Devon Coast National Landscape''s page on Hillsborough Hillfort replaces it; the Megalithic Portal names the same hillfort.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('19e57e66-7781-42ef-88d6-cb2d5327b8f2'::uuid, 'geom', 'SRID=4326;POINT(18.874376 52.409181)', '0101000020E61000004F084BBC01DC324006C4A752AD344A40', 'fields-wd1-2026-09-26b-s002-rollback:19e57e66-7781-42ef-88d6-cb2d5327b8f2:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E61000004F084BBC01DC324006C4A752AD344A40'' restored on Wietrzychowice, Kuyavian-Pomeranian Voivodeship', '[{"source": "https://www.megalithic.co.uk/article.php?sid=20149", "url": "https://www.megalithic.co.uk/article.php?sid=20149", "quote": "Latitude: 52.409181N Longitude: 18.874376E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5775787994", "url": "https://www.openstreetmap.org/node/5775787994", "quote": "52.4091379, 18.8752531", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q71990960", "url": "https://www.wikidata.org/wiki/Q71990960", "quote": "52°24''31.921\"N, 18°52''18.095\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Kuyavian long barrows stand in a forest about 1 km from the centre of Wietrzychowice, according to the heritage register; the stored point is the village''s. The Megalithic Portal point for the barrows, OpenStreetMap''s node for the central tomb 3 and the Wikidata item of the archaeological reserve lie within 0.25 km of each other, about 1 km east-south-east of the stored point, so the point is replaced.", "value_page": null}]'::jsonb),
    ('19e57e66-7781-42ef-88d6-cb2d5327b8f2'::uuid, 'lat', '52.409181', '52.41153939429937', 'fields-wd1-2026-09-26b-s002-rollback:19e57e66-7781-42ef-88d6-cb2d5327b8f2:lat', 'rollback of fields-wd1-2026-09-26b-s002: lat ''52.41153939429937'' restored on Wietrzychowice, Kuyavian-Pomeranian Voivodeship', '[{"source": "https://www.megalithic.co.uk/article.php?sid=20149", "url": "https://www.megalithic.co.uk/article.php?sid=20149", "quote": "Latitude: 52.409181N Longitude: 18.874376E", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/5775787994", "url": "https://www.openstreetmap.org/node/5775787994", "quote": "52.4091379, 18.8752531", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q71990960", "url": "https://www.wikidata.org/wiki/Q71990960", "quote": "52°24''31.921\"N, 18°52''18.095\"E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Kuyavian long barrows stand in a forest about 1 km from the centre of Wietrzychowice, according to the heritage register; the stored point is the village''s. The Megalithic Portal point for the barrows, OpenStreetMap''s node for the central tomb 3 and the Wikidata item of the archaeological reserve lie within 0.25 km of each other, about 1 km east-south-east of the stored point, so the point is replaced.", "value_page": null}]'::jsonb),
