    ('19e57e66-7781-42ef-88d6-cb2d5327b8f2'::uuid, 'site_type', 'Barrow', 'Mound/tumulus', 'fields-wd1-2026-09-26b-s002-rollback:19e57e66-7781-42ef-88d6-cb2d5327b8f2:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Mound/tumulus'' restored on Wietrzychowice, Kuyavian-Pomeranian Voivodeship', '[{"source": "https://www.megalithic.co.uk/article.php?sid=20149", "url": "https://www.megalithic.co.uk/article.php?sid=20149", "quote": "Type: Long Barrow", "outcome": "found"}, {"source": "https://medievalheritage.eu/en/main-page/heritage/poland/wietrzychowice-long-barrows/", "url": "https://medievalheritage.eu/en/main-page/heritage/poland/wietrzychowice-long-barrows/", "quote": "The long barrows of Wietrzychowice were erected by the tribes of shepherds and farmers living in the surrounding areas around 3500 BC.", "outcome": "found"}, {"source": "https://zabytek.pl/en/obiekty/wietrzychowice-grobowce-kujawskie", "url": "https://zabytek.pl/en/obiekty/wietrzychowice-grobowce-kujawskie", "quote": "Kuyavian tombs barrow 4th millennium BC Wietrzychowice", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Megalithic Portal, medievalheritage.eu and the heritage register (category ''barrow'') all describe the site as a group of Neolithic long barrows, the megalithic Kuyavian tombs. ''Barrow'' is more specific than the stored ''Mound/tumulus''.", "value_page": null}]'::jsonb),
    ('19e57e66-7781-42ef-88d6-cb2d5327b8f2'::uuid, 'source_url', 'https://pl.wikipedia.org/wiki/Park_Kulturowy_Wietrzychowice', 'https://en.wikipedia.org/wiki/Wietrzychowice,_Kuyavian-Pomeranian_Voivodeship', 'fields-wd1-2026-09-26b-s002-rollback:19e57e66-7781-42ef-88d6-cb2d5327b8f2:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Wietrzychowice,_Kuyavian-Pomeranian_Voivodeship'' restored on Wietrzychowice, Kuyavian-Pomeranian Voivodeship', '[{"source": "https://pl.wikipedia.org/wiki/Park_Kulturowy_Wietrzychowice", "url": "https://pl.wikipedia.org/wiki/Park_Kulturowy_Wietrzychowice", "quote": "Park Kulturowy Wietrzychowice – park kulturowy utworzony w 2006 roku w celu ochrony sześciu grobowców kujawskich", "outcome": "found"}, {"source": "https://zabytek.pl/en/obiekty/wietrzychowice-grobowce-kujawskie", "url": "https://zabytek.pl/en/obiekty/wietrzychowice-grobowce-kujawskie", "quote": "The tombs in Wietrzychowice are remnants of a cemetery which was used in the 4th millennium BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0116)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia URL is the village''s article. The Polish Wikipedia article on the Wietrzychowice Cultural Park covers the protected group of Kuyavian tombs itself, and the heritage register describes the same cemetery of tombs.", "value_page": {"lang": "pl", "problem": null, "resolved_title": "Park Kulturowy Wietrzychowice", "unreadable": false, "wikibase_item": "Q140921253"}}]'::jsonb),
    ('19ecf84c-4c48-46ec-9685-c87ddfdf65ef'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:19ecf84c-4c48-46ec-9685-c87ddfdf65ef:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Vindonissa', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-100) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('19ecf84c-4c48-46ec-9685-c87ddfdf65ef'::uuid, 'period_start', '-100', '1', 'fields-wd1-2026-09-26b-s002-rollback:19ecf84c-4c48-46ec-9685-c87ddfdf65ef:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Vindonissa', '[{"source": "https://en.wikipedia.org/wiki/Vindonissa", "url": "https://en.wikipedia.org/wiki/Vindonissa", "quote": "The first settlement of Vindonissa was a 1st-century BC Helvetii fortified village on the peninsula between the Aare and Reuss rivers.", "outcome": "found"}, {"source": "https://hls-dhs-dss.ch/de/articles/012287/", "url": "https://hls-dhs-dss.ch/de/articles/012287/", "quote": "Archäologische Funde belegen eine Nutzung der Siedlung im fortgeschrittenen 1. Jahrhundert v.Chr.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia and the Historical Dictionary of Switzerland both trace Vindonissa to a late Celtic (Helvetian) fortified settlement on the Windisch spur, used in the 1st century BC, before the Augustan military post (c. 15 BC) and the legionary camp (c. AD 15); the start is the 1st century BC (-100), not the stored AD 1. The possible Late Bronze Age pits on the periphery are only a probable separate settlement.", "value_page": null}]'::jsonb),
    ('19ecf84c-4c48-46ec-9685-c87ddfdf65ef'::uuid, 'site_type', 'Fortress', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:19ecf84c-4c48-46ec-9685-c87ddfdf65ef:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Vindonissa', '[{"source": "https://legionaryfortresses.info/windisch.htm", "url": "https://legionaryfortresses.info/windisch.htm", "quote": "which provides a tour of the visible remains of Vindonissa fortress.", "outcome": "found"}, {"source": "https://hls-dhs-dss.ch/de/articles/012287/", "url": "https://hls-dhs-dss.ch/de/articles/012287/", "quote": "Römisches Legionslager des 1. Jahrhunderts n.Chr., Vicus, spätantikes Castrum", "outcome": "found"}, {"source": "https://www.museumaargau.ch/en/legionary-trail", "url": "https://www.museumaargau.ch/en/legionary-trail", "quote": "Immerse yourself in the world of Switzerland''s only Roman legionary camp on the Vindonissa Legionary Trail!", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "Vindonissa is above all a Roman legionary fortress (Legionslager of the 13th, 21st and 11th legions, later a late-Roman castrum), as the legionary-fortress gazetteer, the HLS and Museum Aargau describe it; its vicus was an adjunct, so Fortress fits better than City/town/settlement.", "value_page": null}]'::jsonb),
    ('1a26d6f1-d77a-4bb4-a018-afb806a4cd15'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1a26d6f1-d77a-4bb4-a018-afb806a4cd15:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Roman Kilns of El Rinconcillo, Algeciras', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-100) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1a26d6f1-d77a-4bb4-a018-afb806a4cd15'::uuid, 'period_start', '-100', '1', 'fields-wd1-2026-09-26b-s002-rollback:1a26d6f1-d77a-4bb4-a018-afb806a4cd15:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Roman Kilns of El Rinconcillo, Algeciras', '[{"source": "https://es.wikipedia.org/wiki/Hornos_romanos_de_El_Rinconcillo", "url": "https://es.wikipedia.org/wiki/Hornos_romanos_de_El_Rinconcillo", "quote": "Se dataron entre los siglos I a. C. y I d. C.", "outcome": "found"}, {"source": "https://www.algeciras.es/es/detalle-de-noticia/El-Ayuntamiento-finaliza-las-obras-para-proteger-los-hornos-romanos-del-Rinconcillo/", "url": "https://www.algeciras.es/es/detalle-de-noticia/El-Ayuntamiento-finaliza-las-obras-para-proteger-los-hornos-romanos-del-Rinconcillo/", "quote": "Forma parte de un taller más amplio compuesto por al menos cuatro estructuras de combustión que produjeron envases, entre el siglo I antes de Cristo y el I después de Cristo", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0133)", "decision": "replace", "status": "MISSING", "reasoning": "Spanish Wikipedia says the kilns were dated between the 1st century BC and the 1st century AD, and the city of Algeciras says the workshop produced containers between the 1st century BC and the 1st century AD. The attested start is the 1st century BC (-100), in the 500 BC - 1 AD bucket, not the stored 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('1a26d6f1-d77a-4bb4-a018-afb806a4cd15'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:1a26d6f1-d77a-4bb4-a018-afb806a4cd15:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Roman Kilns of El Rinconcillo, Algeciras', '[{"source": "https://en.wikipedia.org/wiki/Roman_kilns_of_El_Rinconcillo", "url": "https://en.wikipedia.org/wiki/Roman_kilns_of_El_Rinconcillo", "quote": "The archaeological site consists of two furnaces attached together to form a single unit.", "outcome": "found"}, {"source": "https://www.algeciras.es/es/detalle-de-noticia/El-Ayuntamiento-finaliza-las-obras-para-proteger-los-hornos-romanos-del-Rinconcillo/", "url": "https://www.algeciras.es/es/detalle-de-noticia/El-Ayuntamiento-finaliza-las-obras-para-proteger-los-hornos-romanos-del-Rinconcillo/", "quote": "La aplicación de este sistema permitirá la estabilización de los hornos hasta su excavación y posterior puesta en valor.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0133)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a pair of Roman amphora kilns of a pottery workshop, not a settlement: Wikipedia calls it an archaeological site of two furnaces, and the city of Algeciras describes the buried kilns awaiting excavation. No canonical type names a kiln or workshop, so the generic Archaeological site replaces the wrong City/town/settlement.", "value_page": null}]'::jsonb),
    ('1aabb9f3-327b-48d5-9fee-045f7ebd4f1f'::uuid, 'period_name', '3000 - 1500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:1aabb9f3-327b-48d5-9fee-045f7ebd4f1f:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Numantia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2500) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1aabb9f3-327b-48d5-9fee-045f7ebd4f1f'::uuid, 'period_start', '-2500', '-500', 'fields-wd1-2026-09-26b-s002-rollback:1aabb9f3-327b-48d5-9fee-045f7ebd4f1f:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Numantia', '[{"source": "https://www.turismocastillayleon.com/es/arte-cultura-patrimonio/yacimientos-arqueologicos/numancia", "url": "https://www.turismocastillayleon.com/es/arte-cultura-patrimonio/yacimientos-arqueologicos/numancia", "quote": "La primera ocupación del Cerro de la Muela se remonta al Calcolítico e inicios de la Edad del Bronce (2500 1600 a. C.).", "outcome": "found"}, {"source": "https://es.wikipedia.org/wiki/Numancia", "url": "https://es.wikipedia.org/wiki/Numancia", "quote": "Los primeros asentamientos humanos en Numancia se establecieron en el III milenio a. C.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Junta de Castilla y León dates the first occupation of the Cerro de la Muela, the hill of Numantia, to the Chalcolithic and early Bronze Age (2500-1600 BC), and Wikipedia puts the first settlements in the 3rd millennium BC. The site''s history therefore begins c. 2500 BC, in the 3000 - 1500 BC bucket, not with the Celtiberian town of c. 500 BC.", "value_page": null}]'::jsonb),
    ('1ac14890-b87e-43e5-a108-57fc4c51c6b2'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1ac14890-b87e-43e5-a108-57fc4c51c6b2:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Pilares do Lena', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1ac14890-b87e-43e5-a108-57fc4c51c6b2'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s002-rollback:1ac14890-b87e-43e5-a108-57fc4c51c6b2:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Pilares do Lena', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0120)", "decision": "clear", "status": "MISSING", "reasoning": "The Lena Pillars are a natural rock formation of Cambrian limestones, shaped as a landform in geological time; no source gives a construction, foundation or occupation date for them, and the park''s 1994/1995 and UNESCO 2012 dates are designations, so the stored 1 AD start is unsupported and the field is emptied.", "value_page": null}]'::jsonb),
    ('1ac1779a-749a-4726-a671-d49a3d1b16e2'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:1ac1779a-749a-4726-a671-d49a3d1b16e2:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Vescia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1ac1779a-749a-4726-a671-d49a3d1b16e2'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s002-rollback:1ac1779a-749a-4726-a671-d49a3d1b16e2:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Vescia', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0089)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates the foundation or first occupation of Vescia; the sources give only its role in the Latin War and its destruction by Rome (340 or 314 BC), which are not a start date.", "value_page": null}]'::jsonb),
