    ('1ada3660-1f43-4840-b8a0-f75580a45a6a'::uuid, 'site_type', 'City', 'Megalithic stones', 'fields-wd1-2026-09-26b-s002-rollback:1ada3660-1f43-4840-b8a0-f75580a45a6a:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic stones'' restored on Khoms', '[{"source": "https://en.wikipedia.org/wiki/Leptis_Magna", "url": "https://en.wikipedia.org/wiki/Leptis_Magna", "quote": "was a prominent city of the Carthaginian Empire and Roman Libya at the mouth of the Wadi Lebda in the Mediterranean.", "outcome": "found"}, {"source": "https://www.worldhistory.org/Lepcis_Magna/", "url": "https://www.worldhistory.org/Lepcis_Magna/", "quote": "Leptis Magna (aka Lepcis Magna), located in western Libya, North Africa, was a Phoenician city founded by Tyre in the 7th century BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0093)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the ancient site at Khoms, Leptis Magna, as a city (Punic, then Roman); nothing describes it as megalithic stones, so the type is City.", "value_page": null}]'::jsonb),
    ('1ada3660-1f43-4840-b8a0-f75580a45a6a'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Leptis_Magna', 'https://en.wikipedia.org/wiki/Al-Khums', 'fields-wd1-2026-09-26b-s002-rollback:1ada3660-1f43-4840-b8a0-f75580a45a6a:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Al-Khums'' restored on Khoms', '[{"source": "https://en.wikipedia.org/wiki/Leptis_Magna", "url": "https://en.wikipedia.org/wiki/Leptis_Magna", "quote": "Lepcis (Khoms)", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Leptis_Magna", "url": "https://en.wikipedia.org/wiki/Leptis_Magna", "quote": "Its ruins are within present-day Al-Khums, Libya, 130 km (81 mi) east of Tripoli.", "outcome": "found"}, {"source": "https://www.romanports.org/en/the-ports/102-lepcis-magna.html", "url": "https://www.romanports.org/en/the-ports/102-lepcis-magna.html", "quote": "The ruins are near modern Khoms in Libya, about 130 kms east of Tripoli, where the Wadi Lebda reaches the coast.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0093)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Al-Khums article is about the modern city and municipality; the ancient site at Khoms is Leptis Magna, whose own English Wikipedia article lists it as ''Lepcis (Khoms)'' and places its ruins within present-day Al-Khums, as the Roman Ports project also does.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Leptis Magna", "unreadable": false, "wikibase_item": "Q191504"}}]'::jsonb),
    ('1ae9f44c-ebe7-454c-8c55-58efe28c0376'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s002-rollback:1ae9f44c-ebe7-454c-8c55-58efe28c0376:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''4500 - 3000 BC'' restored on Anemospilia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1800) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1ae9f44c-ebe7-454c-8c55-58efe28c0376'::uuid, 'period_start', '-1800', '-4500', 'fields-wd1-2026-09-26b-s002-rollback:1ae9f44c-ebe7-454c-8c55-58efe28c0376:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-4500'' restored on Anemospilia', '[{"source": "https://en.wikipedia.org/wiki/Minoan_religion", "url": "https://en.wikipedia.org/wiki/Minoan_religion", "quote": "in a MMII (1800–1700 BC) building near Mount Juktas", "outcome": "found"}, {"source": "https://ruralgreece.gr/en/pois/archaiologikoi-choroi-archanon-giouchta/", "url": "https://ruralgreece.gr/en/pois/archaiologikoi-choroi-archanon-giouchta/", "quote": "It seems that the temple was destroyed in a violent manner during an earthquake, circa 1700 BC, before it had existed for a century.", "outcome": "found"}, {"source": "http://www.minoancrete.com/anemospilia.htm", "url": "http://www.minoancrete.com/anemospilia.htm", "quote": "The ''temple'' was destroyed early in the 17th century BCE, as witnessed by finds of MM II and MM IIIA pottery styles on the site.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia dates the Anemospilia building to Middle Minoan II (1800-1700 BC); Rural Greece says the Protopalatial temple was destroyed c. 1700 BC before it had stood a century, and Minoan Crete dates its destruction to the early 17th century BC with MM II pottery. The start lies in 3000 - 1500 BC, not in the stored bucket 4500 - 3000 BC.", "value_page": null}]'::jsonb),
    ('1b0139f7-0c1f-4e6b-b64a-a176296a8185'::uuid, 'period_name', '1500 - 500 BC', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s002-rollback:1b0139f7-0c1f-4e6b-b64a-a176296a8185:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''3000 - 1500 BC'' restored on Eflatun Pınar Hitit Anıtı', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-1300) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1b0139f7-0c1f-4e6b-b64a-a176296a8185'::uuid, 'period_start', '-1300', '-3000', 'fields-wd1-2026-09-26b-s002-rollback:1b0139f7-0c1f-4e6b-b64a-a176296a8185:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-3000'' restored on Eflatun Pınar Hitit Anıtı', '[{"source": "https://www.megalithic.co.uk/article.php?sid=15981", "url": "https://www.megalithic.co.uk/article.php?sid=15981", "quote": "Probably dating from the late 13th century BCE.", "outcome": "found"}, {"source": "https://www.hittitemonuments.com/eflatunpinar/index.htm", "url": "https://www.hittitemonuments.com/eflatunpinar/index.htm", "quote": "this monument may be dated to the second half of the 13th century BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "MISSING", "reasoning": "The Megalithic Portal and Hittite Monuments both date the Hittite spring monument to the (late) 13th century BCE, the Hittite Empire period Wikipedia also gives; that is -1300, in the 1500 - 500 BC bucket, not the stored 3000 - 1500 BC one.", "value_page": null}]'::jsonb),
    ('1b0139f7-0c1f-4e6b-b64a-a176296a8185'::uuid, 'site_type', 'Sacred site', 'Megalithic stones', 'fields-wd1-2026-09-26b-s002-rollback:1b0139f7-0c1f-4e6b-b64a-a176296a8185:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic stones'' restored on Eflatun Pınar Hitit Anıtı', '[{"source": "https://en.wikipedia.org/wiki/Eflatun_P%C4%B1nar", "url": "https://en.wikipedia.org/wiki/Eflatun_P%C4%B1nar", "quote": "a sacred pool monument was built here in trachyte ashlar masonry dedicated to the sacred spring cult of ancient Hittites", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=15981", "url": "https://www.megalithic.co.uk/article.php?sid=15981", "quote": "A Hittite spring and monument displaying the gods of earth and sky, in Konya Province, Turkey", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes Eflatun Pınar as a Hittite sacred pool monument built for the cult of a sacred spring, and the Megalithic Portal lists it as a Hittite spring and monument (type Holy Well or Sacred Spring); it is a spring sanctuary, not megalithic stones, so the type becomes Sacred site.", "value_page": null}]'::jsonb),
