    ('1b25156f-6212-4c62-a58e-9c6b846fa8f1'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:1b25156f-6212-4c62-a58e-9c6b846fa8f1:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Upper Plym Valley', '[{"source": "https://en.wikipedia.org/wiki/Upper_Plym_Valley", "url": "https://en.wikipedia.org/wiki/Upper_Plym_Valley", "quote": "particularly noted for a large array of archaeological sites ranging from prehistoric", "outcome": "found"}, {"source": "https://www.english-heritage.org.uk/visit/places/upper-plym-valley/history/", "url": "https://www.english-heritage.org.uk/visit/places/upper-plym-valley/history/", "quote": "The Upper Plym Valley is English Heritage’s largest site. It has an extraordinary concentration of stone remains littered across an area of 6 square miles, making it one of the richest archaeological landscapes of Dartmoor.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0047)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and English Heritage describe the Upper Plym Valley as an archaeological landscape of some 300 Bronze Age, medieval and later sites (settlements, cairns, stone rows, farms, warrens, tin works), not a single settlement; no specific type covers the whole, so the generic Archaeological site applies.", "value_page": null}]'::jsonb),
