    ('1b51e95a-6d3b-4cd1-b3ed-da5f4ab8a501'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:1b51e95a-6d3b-4cd1-b3ed-da5f4ab8a501:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on The Wrekin', '[{"source": "https://en.wikipedia.org/wiki/The_Wrekin", "url": "https://en.wikipedia.org/wiki/The_Wrekin", "quote": "It is thought the fort was built by the Cornovii tribe and was once their capital.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=4939", "url": "https://www.megalithic.co.uk/article.php?sid=4939", "quote": "Type: Hillfort", "outcome": "found"}, {"source": "https://www.wellingtonla21.org.uk/the-hillfort/", "url": "https://www.wellingtonla21.org.uk/the-hillfort/", "quote": "Archaeological evidence suggests that a small cluster of these buildings were burnt down in about 450BC, an act that may have led to the construction of the first defences on the hill at a similar date.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0046)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia, the Megalithic Portal (type Hillfort) and Wellington LA21 all describe the site as an Iron Age hill fort with ramparts and gates on the summit; no source calls it a fortress or citadel, so the type is Fort.", "value_page": null}]'::jsonb),
    ('1b51e95a-6d3b-4cd1-b3ed-da5f4ab8a501'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=4939', 'https://en.wikipedia.org/wiki/The_Wrekin', 'fields-wd1-2026-09-26b-s002-rollback:1b51e95a-6d3b-4cd1-b3ed-da5f4ab8a501:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/The_Wrekin'' restored on The Wrekin', '[{"source": "https://www.megalithic.co.uk/article.php?sid=4939", "url": "https://www.megalithic.co.uk/article.php?sid=4939", "quote": "Site Name: The Wrekin Alternative Name: Cuckoo’s Cup, Raven’s Bowl", "outcome": "found"}, {"source": "https://www.wellingtonla21.org.uk/the-hillfort/", "url": "https://www.wellingtonla21.org.uk/the-hillfort/", "quote": "The Wrekin is a scheduled ancient monument with a human history that dates back beyond the Iron Age to 1000BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0046)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill (and royal forest), with one paragraph on the fort; the Megalithic Portal entry is devoted to The Wrekin hillfort itself, and Wellington LA21''s hillfort page independently describes the same monument.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('1b824103-b553-450d-9901-ba645d7d7a09'::uuid, 'site_type', 'Settlement', 'Ruin', 'fields-wd1-2026-09-26b-s002-rollback:1b824103-b553-450d-9901-ba645d7d7a09:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Ruin'' restored on Roman Ruins of Tróia', '[{"source": "https://books.openedition.org/pccj/1696", "url": "https://books.openedition.org/pccj/1696", "quote": "There is no doubt that it was a large settlement.", "outcome": "found"}, {"source": "https://www.historyhit.com/locations/roman-ruins-of-troia/", "url": "https://www.historyhit.com/locations/roman-ruins-of-troia/", "quote": "The ruins of the Roman settlement of Troia in Portugal contain the remains of an important trading centre that grew into a small residential settlement.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0119)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavators call Tróia a large settlement (debating whether it was an industrial quarter, a vicus or a city) and History Hit calls it a Roman settlement; the register calls it an urban-industrial agglomeration. Settlement is the most specific type the sources agree on; ''Ruin'' is too generic and ''City'' is disputed.", "value_page": null}]'::jsonb),
    ('1b82a32d-cf01-4735-94c2-7df578796ce5'::uuid, 'period_name', '500 - 1000 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1b82a32d-cf01-4735-94c2-7df578796ce5:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Bars-Hot', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(901) = ''500 - 1000 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1b82a32d-cf01-4735-94c2-7df578796ce5'::uuid, 'period_start', '901', '1', 'fields-wd1-2026-09-26b-s002-rollback:1b82a32d-cf01-4735-94c2-7df578796ce5:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Bars-Hot', '[{"source": "https://www.steppe-mongolia.com/discover-mongolia/destinations/kherlen_bars_city", "url": "https://www.steppe-mongolia.com/discover-mongolia/destinations/kherlen_bars_city", "quote": "Kherlen Bars City is an archaeological site located in eastern Mongolia, once a major fortified city during the time of the Khitan Liao Dynasty (10th–12th century).", "outcome": "found"}, {"source": "https://mongolschinaandthesilkroad.blogspot.com/2014/06/ruins-of-kherlen-bar-from-khitan-period.html", "url": "https://mongolschinaandthesilkroad.blogspot.com/2014/06/ruins-of-kherlen-bar-from-khitan-period.html", "quote": "The walled city of Kherlen Bars in Dornod province, far eastern Mongolia, was a leading Khitan urban center dating to ca. 10th - 12th century.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0098)", "decision": "replace", "status": "MISSING", "reasoning": "Bars-Hot (Kherlen Bars) is the walled city built by the Khitans; Steppe Mongolia and the Mongols, China and the Silk Road site both date it to the 10th-12th century (Wikipedia dates its pagoda to the 11th), so the start is the 10th century (901), in the 500-1000 AD bucket, not the stored 1-500 AD.", "value_page": null}]'::jsonb),
    ('1be6202f-f47a-40f8-8b07-9fe22cc95000'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1be6202f-f47a-40f8-8b07-9fe22cc95000:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1000 - 1500 AD'' restored on Iskuqucha', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1be6202f-f47a-40f8-8b07-9fe22cc95000'::uuid, 'period_start', NULL, '1400', 'fields-wd1-2026-09-26b-s002-rollback:1be6202f-f47a-40f8-8b07-9fe22cc95000:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1400'' restored on Iskuqucha', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call the site only ''prehispanic'' (Andina, the 2010 declaration) and give no date or period. The stored 1400 has no support, so the field is cleared.", "value_page": null}]'::jsonb),
    ('1be6202f-f47a-40f8-8b07-9fe22cc95000'::uuid, 'site_type', 'Archaeological site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:1be6202f-f47a-40f8-8b07-9fe22cc95000:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Iskuqucha', '[{"source": "https://en.wikipedia.org/wiki/Iskuqucha", "url": "https://en.wikipedia.org/wiki/Iskuqucha", "quote": "is an archaeological site in Peru. It is located in the Junín Region, Yauli Province, La Oroya District.", "outcome": "found"}, {"source": "https://andina.pe/agencia/noticia-declaran-patrimonio-cultural-de-nacion-a-centro-arqueologico-izcucocha-junin-327899.aspx", "url": "https://andina.pe/agencia/noticia-declaran-patrimonio-cultural-de-nacion-a-centro-arqueologico-izcucocha-junin-327899.aspx", "quote": "El Ministerio de Cultura declaró Patrimonio Cultural de la Nación al sitio arqueológico prehispánico Izcucocha, ubicado en la provincia de Yauli, en el departamento de Junín", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0110)", "decision": "replace", "status": "MISSING", "reasoning": "Both independent sources describe Izcucocha only as a (prehispanic) archaeological site, and nothing readable calls it a city, town or settlement. The generic type Archaeological site is the most specific one the sources support.", "value_page": null}]'::jsonb),
    ('1c0baadb-054d-4ffc-be2a-9da571437fb2'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1c0baadb-054d-4ffc-be2a-9da571437fb2:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Oinoanda', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-200) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1c0baadb-054d-4ffc-be2a-9da571437fb2'::uuid, 'period_start', '-200', '1', 'fields-wd1-2026-09-26b-s002-rollback:1c0baadb-054d-4ffc-be2a-9da571437fb2:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Oinoanda', '[{"source": "https://www.lycianmonuments.com/oinoanda/", "url": "https://www.lycianmonuments.com/oinoanda/", "quote": "The earliest securely dated structure is the Hellenistic city wall, which dates to the 2nd century BCE.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Oenoanda", "url": "https://en.wikipedia.org/wiki/Oenoanda", "quote": "It seems that Oenoanda became a colony of Termessos about 200-190 BC and was also called Termessos Minor", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0146)", "decision": "replace", "status": "MISSING", "reasoning": "Lycian Monuments names the Hellenistic city wall of the 2nd century BCE as the earliest securely dated structure (the Hittite Wiyanawanda identification is debated), and Wikipedia dates the Termessian colony to about 200-190 BC; the start is c. 200 BC, in the 500 BC - 1 AD bucket, not 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('1c0baadb-054d-4ffc-be2a-9da571437fb2'::uuid, 'site_type', 'City', 'Megalithic walls', 'fields-wd1-2026-09-26b-s002-rollback:1c0baadb-054d-4ffc-be2a-9da571437fb2:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic walls'' restored on Oinoanda', '[{"source": "https://en.wikipedia.org/wiki/Oenoanda", "url": "https://en.wikipedia.org/wiki/Oenoanda", "quote": "was a Lycian city, in the upper valley of the River Xanthus", "outcome": "found"}, {"source": "https://www.lycianmonuments.com/oinoanda/", "url": "https://www.lycianmonuments.com/oinoanda/", "quote": "The ruins of Oinoanda are located near the village of İncealiler in the Seydikemer district of Muğla. It was one of the four major cities of the Kibyratis (Kabalis) region, together with Kibyra, Balboura, and Bubon.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0146)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both Wikipedia and Lycian Monuments describe Oinoanda as a city (a Lycian city, one of the four major cities of the Kibyratis); its polygonal wall is one structure of the city, so City replaces Megalithic walls.", "value_page": null}]'::jsonb),
    ('1c18de52-3783-41cb-a3dd-ade50498a974'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:1c18de52-3783-41cb-a3dd-ade50498a974:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Babilonie', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1c18de52-3783-41cb-a3dd-ade50498a974'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s002-rollback:1c18de52-3783-41cb-a3dd-ade50498a974:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Babilonie', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "clear", "status": "MISSING", "reasoning": "The Altertumskommission für Westfalen dates a mould and other finds to the 8th-6th century BC and takes them as probably the beginning of the fortification. English and German Wikipedia instead give 300-150 BC, and EBIDAT and alleburgen.de say only ''pre-Roman Iron Age''. No two independent sources put the start in the same bucket, so the field is emptied (the LWL''s 8th century BC is the best lead for the owner).", "value_page": null}]'::jsonb),
    ('1c18de52-3783-41cb-a3dd-ade50498a974'::uuid, 'site_type', 'Fortification', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:1c18de52-3783-41cb-a3dd-ade50498a974:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Babilonie', '[{"source": "https://en.wikipedia.org/wiki/Babilonie", "url": "https://en.wikipedia.org/wiki/Babilonie", "quote": "The fortification has an area of over 12 hectares.", "outcome": "found"}, {"source": "https://www.altertumskommission.lwl.org/de/forschung/burgen/die-wallburg-babilonie/", "url": "https://www.altertumskommission.lwl.org/de/forschung/burgen/die-wallburg-babilonie/", "quote": "Eine Gussform zur Herstellung von Gewandnadeln kann neben anderen Stücken in das 8. bis 6. Jahrhundert v. Chr. datiert werden und markiert somit wohl den Beginn der Babilonie als Befestigungsanlage.", "outcome": "found"}, {"source": "https://www.ms-visucom.de/cgi-bin/ebidat.pl?m=h&id=4907", "url": "https://www.ms-visucom.de/cgi-bin/ebidat.pl?m=h&id=4907", "quote": "Kurzansprache: Eine eisenzeitliche Wallburg, die in der Karolingerzeit wiederverwendet wurde.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia (a hillfort, ''the fortification''), the LWL Altertumskommission (a ''Wallburg'' and ''Befestigungsanlage'' used as a refuge) and EBIDAT (an Iron Age Wallburg, a ring rampart) all describe a rampart enclosure with palisades, not a citadel or fortress. Fortification is the type they support.", "value_page": null}]'::jsonb),
    ('1c4ac177-bcca-4044-8e2d-4d15fe0606ab'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1c4ac177-bcca-4044-8e2d-4d15fe0606ab:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on City of Enns', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-400) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1c4ac177-bcca-4044-8e2d-4d15fe0606ab'::uuid, 'period_start', '-400', '1', 'fields-wd1-2026-09-26b-s002-rollback:1c4ac177-bcca-4044-8e2d-4d15fe0606ab:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on City of Enns', '[{"source": "https://en.wikipedia.org/wiki/Enns_(town)", "url": "https://en.wikipedia.org/wiki/Enns_(town)", "quote": "Celts settled the land around 400 BC.", "outcome": "found"}, {"source": "https://www.enns.at/Unser_Enns/Stadtgeschichte", "url": "https://www.enns.at/Unser_Enns/Stadtgeschichte", "quote": "Im 4. und 3. Jh. v. Chr. waren es die Kelten, ab 15 v. Chr. die Römer, die den Ennser Raum besiedelten.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "MISSING", "reasoning": "Both Wikipedia and the town''s own history date the first dated settlement of Enns to the Celts around 400 BC (4th century BC), before the Roman occupation from 15 BC and the legionary fortress of c. 205 AD; earlier Neolithic traces are undated. The start therefore lies in the 500 BC - 1 AD bucket, not in the stored 1 - 500 AD bucket.", "value_page": null}]'::jsonb),
    ('1c4ac177-bcca-4044-8e2d-4d15fe0606ab'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Enns_(town)', 'https://en.wikipedia.org/wiki/History', 'fields-wd1-2026-09-26b-s002-rollback:1c4ac177-bcca-4044-8e2d-4d15fe0606ab:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/History'' restored on City of Enns', '[{"source": "https://en.wikipedia.org/wiki/Enns_(town)", "url": "https://en.wikipedia.org/wiki/Enns_(town)", "quote": "Enns was one of the first places in Austria to receive town rights.", "outcome": "found"}, {"source": "https://www.enns.at/Unser_Enns/Stadtgeschichte", "url": "https://www.enns.at/Unser_Enns/Stadtgeschichte", "quote": "Der Ennser Boden wurde schon sehr früh besiedelt. Die Besiedelung reicht bis in die Jungsteinzeit zurück.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0007)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic article History; the English Wikipedia article of the site''s own item (Q260089) is Enns (town), which covers the town''s Celtic, Roman and later history.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Enns (town)", "unreadable": false, "wikibase_item": "Q260089"}}]'::jsonb),
    ('1c573084-c7d7-4072-84c3-30adc4b6c521'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:1c573084-c7d7-4072-84c3-30adc4b6c521:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Natural Park Gradistea Muncelului - Cioclovina', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1c573084-c7d7-4072-84c3-30adc4b6c521'::uuid, 'period_start', NULL, '-100', 'fields-wd1-2026-09-26b-s002-rollback:1c573084-c7d7-4072-84c3-30adc4b6c521:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-100'' restored on Natural Park Gradistea Muncelului - Cioclovina', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0120)", "decision": "clear", "status": "MISSING", "reasoning": "A natural park has no ancient start: Wikipedia and the park administration date only its designation (Law 5/2000, earlier 1979), which is not a site start; the Dacian fortresses and caves inside it are separate sites, so the field is emptied.", "value_page": null}]'::jsonb),
    ('1c573084-c7d7-4072-84c3-30adc4b6c521'::uuid, 'site_type', 'Natural feature', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:1c573084-c7d7-4072-84c3-30adc4b6c521:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Natural Park Gradistea Muncelului - Cioclovina', '[{"source": "https://en.wikipedia.org/wiki/Gr%C4%83di%C8%99tea_Muncelului-Cioclovina_Natural_Park", "url": "https://en.wikipedia.org/wiki/Gr%C4%83di%C8%99tea_Muncelului-Cioclovina_Natural_Park", "quote": "is a protected area (natural park category V IUCN) situated in Romania, in Hunedoara County.", "outcome": "found"}, {"source": "https://gradiste.ro/localizare.html", "url": "https://gradiste.ro/localizare.html", "quote": "Zona inclusă în limitele stabilite prin Hotărârea Guvernului nr. 230 din 04.03.2003 pentru Parcul Natural Grădiştea Muncelului-Cioclovina este situată în masivul Munţii Şureanu", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0120)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site named here is the natural park itself, a protected mountain landscape of forests, karst, caves and canyons (Wikipedia; the park administration''s own page), not a fortress; Natural feature is the canonical type that holds for a natural park.", "value_page": null}]'::jsonb),
    ('1c57e536-a94f-4b39-a578-a448932a4cb5'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:1c57e536-a94f-4b39-a578-a448932a4cb5:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Ancient Theatre of Megalopolis', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-370) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1c57e536-a94f-4b39-a578-a448932a4cb5'::uuid, 'period_start', '-370', '1', 'fields-wd1-2026-09-26b-s002-rollback:1c57e536-a94f-4b39-a578-a448932a4cb5:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Ancient Theatre of Megalopolis', '[{"source": "https://es.wikipedia.org/wiki/Teatro_de_Megal%C3%B3polis", "url": "https://es.wikipedia.org/wiki/Teatro_de_Megal%C3%B3polis", "quote": "Se construyó alrededor del año 370 a. C., inmediatamente después de la construcción de la Megalópolis.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=15717", "url": "https://www.megalithic.co.uk/article.php?sid=15717", "quote": "The most important monuments include the 4th century BCE theatre", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "Spanish Wikipedia dates the theatre''s construction to about 370 BC, right after the founding of Megalopolis, and the Megalithic Portal calls it the 4th century BCE theatre; the start lies in 500 BC - 1 AD, not in the stored bucket 1 - 500 AD.", "value_page": null}]'::jsonb),
