    ('1c57e536-a94f-4b39-a578-a448932a4cb5'::uuid, 'source_url', 'https://es.wikipedia.org/wiki/Teatro_de_Megal%C3%B3polis', 'https://en.wikipedia.org/wiki/Megalopolis,_Greece', 'fields-wd1-2026-09-26b-s002-rollback:1c57e536-a94f-4b39-a578-a448932a4cb5:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Megalopolis,_Greece'' restored on Ancient Theatre of Megalopolis', '[{"source": "https://es.wikipedia.org/wiki/Teatro_de_Megal%C3%B3polis", "url": "https://es.wikipedia.org/wiki/Teatro_de_Megal%C3%B3polis", "quote": "El Teatro de Megalópolis era un antiguo teatro griego de la ciudad de Megalópolis.", "outcome": "found"}, {"source": "https://topostext.org/place/374221BMTh", "url": "https://topostext.org/place/374221BMTh", "quote": "Theater, Very large theater S of Helisson river, Megalopolis, Arkadia", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0060)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on the town of Megalopolis; the theatre has no English article, and Spanish Wikipedia''s ''Teatro de Megalópolis'' is the site''s own article (linked to the site''s Wikidata item Q22681531), naming the same theatre ToposText lists.", "value_page": {"lang": "es", "problem": null, "resolved_title": "Teatro de Megalópolis", "unreadable": false, "wikibase_item": "Q22681531"}}]'::jsonb),
