    ('1ce162fb-4605-4313-b36f-1209718e7b1e'::uuid, 'period_start', '-500', '-1500', 'fields-wd1-2026-09-26b-s002-rollback:1ce162fb-4605-4313-b36f-1209718e7b1e:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Pistiros', '[{"source": "https://en.wikipedia.org/wiki/Pistiros", "url": "https://en.wikipedia.org/wiki/Pistiros", "quote": "Pistiros was founded in the 3rd quarter of the 5th century BC.", "outcome": "found"}, {"source": "https://www.liverpool.ac.uk/archaeology-classics-and-egyptology/research/projects/ancient-pistiros/", "url": "https://www.liverpool.ac.uk/archaeology-classics-and-egyptology/research/projects/ancient-pistiros/", "quote": "in the period ca. 430-250 BC and beyond.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia dates the foundation of Pistiros to the 5th century BC (third quarter), and the University of Liverpool excavation project dates the occupation of its excavated quarters from ca. 430 BC; the start lies in the 500 BC - 1 AD bucket, not in the stored 1500 - 500 BC one.", "value_page": null}]'::jsonb),
    ('1ce162fb-4605-4313-b36f-1209718e7b1e'::uuid, 'site_type', 'City/town/settlement', 'Megalithic stones', 'fields-wd1-2026-09-26b-s002-rollback:1ce162fb-4605-4313-b36f-1209718e7b1e:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic stones'' restored on Pistiros', '[{"source": "https://www.liverpool.ac.uk/archaeology-classics-and-egyptology/research/projects/ancient-pistiros/", "url": "https://www.liverpool.ac.uk/archaeology-classics-and-egyptology/research/projects/ancient-pistiros/", "quote": "The ancient settlement is rich in finds.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Pistiros", "url": "https://en.wikipedia.org/wiki/Pistiros", "quote": "The city was most likely founded by colonists from the coastal city of Pistyros.", "outcome": "found"}, {"source": "https://www.bulgariancastles.com/gr-septemvri-ukrepen-grad-emporion-pistiros/", "url": "https://www.bulgariancastles.com/gr-septemvri-ukrepen-grad-emporion-pistiros/", "quote": "Античен, укрепен град и емпорион Пистирос се намира на 5.4 km югоизточно по права линия от центъра на град Ветрен.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "The University of Liverpool excavation project calls Pistiros an ancient settlement (a river-port emporium), Wikipedia a city and Bulgarian Castles a fortified town and emporion; it is a settlement, not megalithic stones.", "value_page": null}]'::jsonb),
