    ('1cef72f4-b9d4-4180-b93a-10b0cbe1a234'::uuid, 'period_start', '-900', '-3000', 'fields-wd1-2026-09-26b-s002-rollback:1cef72f4-b9d4-4180-b93a-10b0cbe1a234:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-3000'' restored on Prison of Solomon', '[{"source": "https://www.tehrantimes.com/news/462441/Soleyman-Prison-a-conical-peak-with-fascinating-history", "url": "https://www.tehrantimes.com/news/462441/Soleyman-Prison-a-conical-peak-with-fascinating-history", "quote": "the cone was once enclosed by fortified walls and topped by a religious sanctuary that archaeologists suggest dated to 900 BC.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Prison_of_Solomon", "url": "https://en.wikipedia.org/wiki/Prison_of_Solomon", "quote": "It used to be surrounded by walls and hosted a Mannaean temple in 880–660 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "MISSING", "reasoning": "The earliest human use of the hill is the walled Mannaean sanctuary on its rim, which the Tehran Times dates to about 900 BC and Wikipedia to 880-660 BCE. The stored 3000 BC has no support; the start lies in the 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('1cef72f4-b9d4-4180-b93a-10b0cbe1a234'::uuid, 'site_type', 'Sanctuary', 'Cave Structures', 'fields-wd1-2026-09-26b-s002-rollback:1cef72f4-b9d4-4180-b93a-10b0cbe1a234:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Cave Structures'' restored on Prison of Solomon', '[{"source": "https://www.tehrantimes.com/news/462441/Soleyman-Prison-a-conical-peak-with-fascinating-history", "url": "https://www.tehrantimes.com/news/462441/Soleyman-Prison-a-conical-peak-with-fascinating-history", "quote": "the cone was once enclosed by fortified walls and topped by a religious sanctuary that archaeologists suggest dated to 900 BC.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Prison_of_Solomon", "url": "https://en.wikipedia.org/wiki/Prison_of_Solomon", "quote": "It used to be surrounded by walls and hosted a Mannaean temple in 880–660 BCE.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0079)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Prison of Solomon is not a cave structure: it is a hollow travertine cone whose archaeological remains are a walled religious precinct on its summit, which the Tehran Times calls a sanctuary and Wikipedia a Mannaean temple. Sanctuary fits the walled cult precinct on the natural cone best.", "value_page": null}]'::jsonb),
