    ('1d65f378-c797-47d7-827c-252df5243d13'::uuid, 'lon', '15.146238', '15.166731069652126', 'fields-wd1-2026-09-26b-s002-rollback:1d65f378-c797-47d7-827c-252df5243d13:lon', 'rollback of fields-wd1-2026-09-26b-s002: lon ''15.166731069652126'' restored on Rocca San Felice', '[{"source": "https://www.openstreetmap.org/node/2133554656", "url": "https://www.openstreetmap.org/node/2133554656", "quote": "Location: 40.9747584, 15.1462381", "outcome": "found"}, {"source": "https://it.wikipedia.org/wiki/Lago_Mefite", "url": "https://it.wikipedia.org/wiki/Lago_Mefite", "quote": "40°58′28.88″N 15°08′46.03″E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the sanctuary of Mefitis at the Mefite pool in the Valle d''Ansanto, in the territory of Rocca San Felice; OpenStreetMap''s archaeological-site node ''Mefite'' (40.9747584, 15.1462381) and Italian Wikipedia''s Lago Mefite (40°58′28.88″N 15°08′46.03″E) agree, about 3.2 km north-west of the stored point, which is the village''s point.", "value_page": null}]'::jsonb),
    ('1d65f378-c797-47d7-827c-252df5243d13'::uuid, 'site_type', 'Sanctuary', 'Temple complex', 'fields-wd1-2026-09-26b-s002-rollback:1d65f378-c797-47d7-827c-252df5243d13:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Temple complex'' restored on Rocca San Felice', '[{"source": "https://en.wikipedia.org/wiki/Mefitis", "url": "https://en.wikipedia.org/wiki/Mefitis", "quote": "Cicero and Pliny the Elder both describe the lake of Ampsanctus as deadly,[24] with Pliny more specifically stating that her sanctuary was afflicted with toxic natural gases", "outcome": "found"}, {"source": "https://www.treccani.it/enciclopedia/rocca-san-felice_%28Enciclopedia-dell%27-Arte-Antica%29/", "url": "https://www.treccani.it/enciclopedia/rocca-san-felice_%28Enciclopedia-dell%27-Arte-Antica%29/", "quote": "Il santuario, esplorato tra difficoltà quasi insormontabili a causa del terreno melmoso e delle esalazioni solforose nel ''700 ed in questi ultimi anni, ha dato una serie notevole di oggetti votivi e di monete.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia''s Mefitis article and the Enciclopedia dell''Arte Antica describe the site as the sanctuary (santuario) of Mefitis at the lake of Ampsanctus, known from votive deposits rather than a temple complex; Sanctuary is the fitting type.", "value_page": null}]'::jsonb),
    ('1d65f378-c797-47d7-827c-252df5243d13'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Ampsanctus', 'https://en.wikipedia.org/wiki/Mefitis', 'fields-wd1-2026-09-26b-s002-rollback:1d65f378-c797-47d7-827c-252df5243d13:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Mefitis'' restored on Rocca San Felice', '[{"source": "https://en.wikipedia.org/wiki/Ampsanctus", "url": "https://en.wikipedia.org/wiki/Ampsanctus", "quote": "Close by was a temple of the goddess Mephitis, with a cave from which suffocating vapors rose, and for this reason, the place was brought into connection with the legends of the infernal regions.", "outcome": "found"}, {"source": "https://www.treccani.it/enciclopedia/rocca-san-felice_%28Enciclopedia-dell%27-Arte-Antica%29/", "url": "https://www.treccani.it/enciclopedia/rocca-san-felice_%28Enciclopedia-dell%27-Arte-Antica%29/", "quote": "ROCCA SAN FELICE M. Napoli Santuario di mefite. - Comune della provincia di Avellino nel territorio del quale, nella valle dell''Ansanto, trovasi un cratere semispento ed un laghetto ribollente", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is about the goddess Mefitis; English Wikipedia''s Ampsanctus is about the sacred lake of the Valle d''Ansanto with its temple of Mephitis, the site that the Enciclopedia dell''Arte Antica describes under Rocca San Felice.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Ampsanctus", "unreadable": false, "wikibase_item": "Q3214709"}}]'::jsonb),
    ('1d7c880b-80be-41b1-8be5-58d07a0e5dcd'::uuid, 'geom', 'SRID=4326;POINT(-89.72847 17.79405)', '0101000020E61000001CBDEE57656F56C0127D4CB171CC3140', 'fields-wd1-2026-09-26b-s002-rollback:1d7c880b-80be-41b1-8be5-58d07a0e5dcd:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E61000001CBDEE57656F56C0127D4CB171CC3140'' restored on Naachtun', '[{"source": "https://www.geonames.org/3592293", "url": "https://www.geonames.org/3592293", "quote": "17.79405, -89.72847", "outcome": "found"}, {"source": "https://www.wikidata.org/wiki/Q1770492", "url": "https://www.wikidata.org/wiki/Q1770492", "quote": "17°47''38.6\"N, 89°43''42.5\"W", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0076)", "decision": "replace", "status": "CONFLICT", "reasoning": "GeoNames (Sitio Arqueológico Naachtún) and Wikidata place the site at 17.794, -89.728, where OpenStreetMap maps the monumental Groups C, A and B along the ridge (lon -89.734 to -89.726); the stored point, taken from English Wikipedia''s 17.7978, -89.7403, lies about 1.4 km west of that core, so it is replaced.", "value_page": null}]'::jsonb),
