    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:1da76491-5256-486f-b67e-ff6f762c46b5:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on High Peak, Devon', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'period_start', NULL, '-1000', 'fields-wd1-2026-09-26b-s002-rollback:1da76491-5256-486f-b67e-ff6f762c46b5:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1000'' restored on High Peak, Devon', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "clear", "status": "MISSING", "reasoning": "The Historic England description (as copied by Dartmoor Walks) and the Megalithic Portal say excavation found an Early Neolithic causewayed enclosure and a 5th-6th century AD fortified settlement, not a Late Bronze Age or Iron Age start; only the Megalithic Portal gives a year range (the Neolithic, 4000-2000 BC), and no second source dates the start with a year, century or millennium, so the field is emptied.", "value_page": null}]'::jsonb),
    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:1da76491-5256-486f-b67e-ff6f762c46b5:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on High Peak, Devon', '[{"source": "https://en.wikipedia.org/wiki/High_Peak,_Devon", "url": "https://en.wikipedia.org/wiki/High_Peak,_Devon", "quote": "It features a partially eroded Iron Age hill fort, with pre-Roman and post Roman pottery found there.", "outcome": "found"}, {"source": "http://dartmoorwalks.org.uk/resource/site.php?SiteID=691", "url": "http://dartmoorwalks.org.uk/resource/site.php?SiteID=691", "quote": "High Peak Camp is a multi-period site, which encompasses the buried remains of part of an Early Neolithic causewayed enclosure and the earthworks and buried remains of part of an early medieval fortified settlement dated to the 5th and 6th centuries AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia describes the earthworks on High Peak as a hill fort and the Historic England description quoted by Dartmoor Walks as a fortified settlement with rampart and ditch; no source calls it a fortress or citadel, so the most specific fitting type is Fort.", "value_page": null}]'::jsonb),
    ('1da76491-5256-486f-b67e-ff6f762c46b5'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=43929', 'https://en.wikipedia.org/wiki/High_Peak,_Devon', 'fields-wd1-2026-09-26b-s002-rollback:1da76491-5256-486f-b67e-ff6f762c46b5:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/High_Peak,_Devon'' restored on High Peak, Devon', '[{"source": "https://www.megalithic.co.uk/article.php?sid=43929", "url": "https://www.megalithic.co.uk/article.php?sid=43929", "quote": "High Peak Ancient Settlement Devon", "outcome": "found"}, {"source": "http://dartmoorwalks.org.uk/resource/site.php?SiteID=691", "url": "http://dartmoorwalks.org.uk/resource/site.php?SiteID=691", "quote": "High Peak Camp is a multi-period site", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0036)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the Wikipedia article on the coastal hill; the earthwork site High Peak Camp has no Wikipedia article in any language, and the Historic England entry refuses plain requests, so the Megalithic Portal''s page on the High Peak settlement replaces it; Dartmoor Walks names the same site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
