    ('1e5f61dd-b362-4985-b235-dadeea0eca0f'::uuid, 'period_name', '1000 - 1500 AD', '3000 - 1500 BC', 'fields-wd1-2026-09-26b-s002-rollback:1e5f61dd-b362-4985-b235-dadeea0eca0f:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''3000 - 1500 BC'' restored on Tichit', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1101) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1e5f61dd-b362-4985-b235-dadeea0eca0f'::uuid, 'period_start', '1101', '-2000', 'fields-wd1-2026-09-26b-s002-rollback:1e5f61dd-b362-4985-b235-dadeea0eca0f:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-2000'' restored on Tichit', '[{"source": "https://en.wikipedia.org/wiki/Tichit", "url": "https://en.wikipedia.org/wiki/Tichit", "quote": "The town of Tichitt was founded in the 12th century as a caravan stop on the", "outcome": "found"}, {"source": "https://www.unescotracker.net/sites/703/ancient-ksour-of-ouadane-chinguetti-tichitt-and-oualata", "url": "https://www.unescotracker.net/sites/703/ancient-ksour-of-ouadane-chinguetti-tichitt-and-oualata", "quote": "These four ancient towns, founded in the 11th and 12th centuries, were originally built to serve the important caravan trade routes that began crossing the Sahara.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0094)", "decision": "replace", "status": "MISSING", "reasoning": "The site at this point is the ksar/town of Tichit (the Neolithic settlements are on the Dhar Tichitt cliffs, a separate site); Wikipedia dates the town''s foundation to the 12th century and the UNESCO description of the four ksour, Tichitt among them, to the 11th-12th centuries. The start lies in 1000-1500 AD, not in the stored 3000-1500 BC bucket, so it becomes 1101.", "value_page": null}]'::jsonb),
    ('1e5f61dd-b362-4985-b235-dadeea0eca0f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Tichit', 'https://en.wikipedia.org/wiki/Tichi', 'fields-wd1-2026-09-26b-s002-rollback:1e5f61dd-b362-4985-b235-dadeea0eca0f:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Tichi'' restored on Tichit', '[{"source": "https://en.wikipedia.org/wiki/Tichit", "url": "https://en.wikipedia.org/wiki/Tichit", "quote": "is a village at the foot of the Tagant Plateau in central southern Mauritania that is known for its vernacular architecture and proximity to the Dhar Tichitt archaeological sites.", "outcome": "found"}, {"source": "https://qualla.com/tichit/", "url": "https://qualla.com/tichit/", "quote": "Tichit sits at roughly 18.44°N, 9.49°W on the high plains at the foot of the Tagant escarpment in eastern Mauritania, about 200 km by track east of Tidjikja.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0094)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL points to a non-existent article ''Tichi'' (a typo); the English Wikipedia article ''Tichit'' is the site''s own article, and an independent travel page describes the same town at the same place.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Tichit", "unreadable": false, "wikibase_item": "Q985527"}}]'::jsonb),
    ('1e9f1c86-dabd-4cf8-90f8-87c64a8ccc5c'::uuid, 'period_name', '< 4500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s002-rollback:1e9f1c86-dabd-4cf8-90f8-87c64a8ccc5c:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''4500 - 3000 BC'' restored on Cave of Zeus, Naxos', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-5000) = ''< 4500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1e9f1c86-dabd-4cf8-90f8-87c64a8ccc5c'::uuid, 'period_start', '-5000', '-4000', 'fields-wd1-2026-09-26b-s002-rollback:1e9f1c86-dabd-4cf8-90f8-87c64a8ccc5c:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-4000'' restored on Cave of Zeus, Naxos', '[{"source": "http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=23204", "url": "http://odysseus.culture.gr/h/2/gh251.jsp?obj_id=23204", "quote": "απέδειξαν τη μακραίωνη ανθρώπινη παρουσία, η οποία εμφανίζεται κατά την Τελική Νεολιθική (5η-4η χιλιετία π.Χ.)", "outcome": "found"}, {"source": "https://www.visitgreece.gr/en/experiences/nature/mountains/mount-zas-and-the-cave-of-zeus", "url": "https://www.visitgreece.gr/en/experiences/nature/mountains/mount-zas-and-the-cave-of-zeus", "quote": "From the Final Neolithic period (5th–4th millennium BC) through to the Roman era, the cave served as both a refuge and a place of worship", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0063)", "decision": "replace", "status": "MISSING", "reasoning": "The Greek Ministry of Culture (Odysseus, citing K. Zachos''s excavations) and the Greek National Tourism Organisation both date the first human presence in the Cave of Zas to the Final Neolithic of the 5th-4th millennium BC, and the Foundation of the Hellenic World places an even earlier Late Neolithic phase (Zas I) before it; the start is therefore the 5th millennium BC (-5000), before 4500 BC, not the stored -4000.", "value_page": null}]'::jsonb),
    ('1ec1e384-fe4a-4cf5-bffd-f342e5daa228'::uuid, 'period_name', '1 - 500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:1ec1e384-fe4a-4cf5-bffd-f342e5daa228:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Sigiriya - Peak', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(477) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('1ec1e384-fe4a-4cf5-bffd-f342e5daa228'::uuid, 'period_start', '477', '-500', 'fields-wd1-2026-09-26b-s002-rollback:1ec1e384-fe4a-4cf5-bffd-f342e5daa228:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Sigiriya - Peak', '[{"source": "https://sigiriya.site/", "url": "https://sigiriya.site/", "quote": "Built in 477 AD by King Kasyapa, this granite peak rises 200 meters above the jungle, housing a fortress, gardens, and masterworks of ancient engineering.", "outcome": "found"}, {"source": "https://lankanhistory.com/blog/lankanhistory-com-blog-sigiriya-rock-fortress", "url": "https://lankanhistory.com/blog/lankanhistory-com-blog-sigiriya-rock-fortress", "quote": "477–495 CE – Palaces, gardens, reservoirs and defensive walls are built around and on the rock.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Sigiriya", "url": "https://en.wikipedia.org/wiki/Sigiriya", "quote": "During King Kashyapa''s reign (477–495 CE), Sigiriya was developed into a complex city and fortress.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the summit of the Sigiriya rock; the monks'' rock shelters of the 3rd century BC lie around its base, while the summit palace and citadel were built by King Kashyapa from 477 AD, as the site''s visitor page, Lankan History and Wikipedia state. The start is therefore 477, in the 1 - 500 AD bucket, not 500 BC.", "value_page": null}]'::jsonb),
    ('1ed19de1-b9da-4cfa-a1ec-16693f6cc090'::uuid, 'site_type', 'Burial', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s002-rollback:1ed19de1-b9da-4cfa-a1ec-16693f6cc090:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Necropolis/tombs complex'' restored on Gettlinge Grave Field', '[{"source": "https://www.guidebook-sweden.com/en/guidebook/destination/gettlinge-gravf%C3%A4lt-grave-field-gettlinge", "url": "https://www.guidebook-sweden.com/en/guidebook/destination/gettlinge-gravf%C3%A4lt-grave-field-gettlinge", "quote": "Gettlinge Gravfält is one of the largest and certainly most beautiful prehistoric burial sites on the island of Öland.", "outcome": "found"}, {"source": "https://www.sfv.se/vara-fastigheter/sverige/kalmar-lan/sodra-oelands-gravfalt", "url": "https://www.sfv.se/vara-fastigheter/sverige/kalmar-lan/sodra-oelands-gravfalt", "quote": "Gettlinge gravfält är en nästan två kilometer lång fornlämning i södra Möckleby socken på södra Öland.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is a grave field (gravfält) of more than 200 graves - stone settings, mounds, standing stones and a ship setting; GuidebookSweden calls it a prehistoric burial site and the Swedish state property agency SFV describes the two-kilometre grave field. No source calls it a necropolis or tomb complex, so the stored type is replaced by Burial.", "value_page": null}]'::jsonb),
    ('1ed19de1-b9da-4cfa-a1ec-16693f6cc090'::uuid, 'source_url', 'https://sv.wikipedia.org/wiki/Gettlinge_gravf%C3%A4lt', 'https://en.wikipedia.org/wiki/Gettlinge', 'fields-wd1-2026-09-26b-s002-rollback:1ed19de1-b9da-4cfa-a1ec-16693f6cc090:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Gettlinge'' restored on Gettlinge Grave Field', '[{"source": "https://sv.wikipedia.org/wiki/Gettlinge_gravf%C3%A4lt", "url": "https://sv.wikipedia.org/wiki/Gettlinge_gravf%C3%A4lt", "quote": "Gettlinge gravfält är en fornlämning i Södra Möckleby socken på södra Öland.", "outcome": "found"}, {"source": "https://www.sfv.se/vara-fastigheter/sverige/kalmar-lan/sodra-oelands-gravfalt", "url": "https://www.sfv.se/vara-fastigheter/sverige/kalmar-lan/sodra-oelands-gravfalt", "quote": "Gettlinge gravfält är en nästan två kilometer lång fornlämning i södra Möckleby socken på södra Öland.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0136)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia page is about the village of Gettlinge; the grave field has its own article on Swedish Wikipedia (there is none in English), which SFV''s page on the same grave field confirms.", "value_page": {"lang": "sv", "problem": null, "resolved_title": "Gettlinge gravfält", "unreadable": false, "wikibase_item": "Q1551283"}}]'::jsonb),
    ('1f34f490-a5ef-462d-961e-e4bbd8eb5422'::uuid, 'site_type', 'Theatre', 'Megalithic structures', 'fields-wd1-2026-09-26b-s002-rollback:1f34f490-a5ef-462d-961e-e4bbd8eb5422:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic structures'' restored on Hellenistic-Roman Theatre', '[{"source": "https://www.sydney.edu.au/museum/our-research/paphos-theatre.html", "url": "https://www.sydney.edu.au/museum/our-research/paphos-theatre.html", "quote": "The excavations have revealed a theatre used for performance and entertainment for over six and a half centuries (c.300 BC to the late fourth century AD).", "outcome": "found"}, {"source": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/59FFC9310818070EC225719B003A2EB8?OpenDocument", "url": "https://www.culture.gov.cy/dmculture/DA/DA.nsf/All/59FFC9310818070EC225719B003A2EB8?OpenDocument", "quote": "The construction of the theatre dates to the founding of the city but it went through alterations and its original plan changed during the Roman period.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site is the Hellenistic-Roman theatre of Nea Paphos, described as a theatre by its excavators (University of Sydney) and by the Department of Antiquities; nothing megalithic is involved, so the type is Theatre.", "value_page": null}]'::jsonb),
    ('1f34f490-a5ef-462d-961e-e4bbd8eb5422'::uuid, 'source_url', 'https://www.sydney.edu.au/museum/our-research/paphos-theatre.html', 'https://en.wikipedia.org/wiki/Theatre', 'fields-wd1-2026-09-26b-s002-rollback:1f34f490-a5ef-462d-961e-e4bbd8eb5422:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Theatre'' restored on Hellenistic-Roman Theatre', '[{"source": "https://www.sydney.edu.au/museum/our-research/paphos-theatre.html", "url": "https://www.sydney.edu.au/museum/our-research/paphos-theatre.html", "quote": "The excavations have revealed a theatre used for performance and entertainment for over six and a half centuries (c.300 BC to the late fourth century AD).", "outcome": "found"}, {"source": "https://www.gpsmycity.com/attractions/hellenistic-roman-theatre-62295.html", "url": "https://www.gpsmycity.com/attractions/hellenistic-roman-theatre-62295.html", "quote": "The Hellenistic-Roman Theatre, which once echoed with the voices of actors and the applause of spectators, tells the story of a cultural heritage that spans centuries.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0019)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the generic Wikipedia article on theatre; the site has no Wikipedia article of its own, and the University of Sydney''s ''Paphos theatre'' page is the excavators'' own page on this very monument, which GPSmyCity independently names as the Hellenistic-Roman Theatre of Nea Paphos.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('203fbf02-196b-4853-8504-d35a34085345'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s002-rollback:203fbf02-196b-4853-8504-d35a34085345:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Necropolis/tombs complex'' restored on Madghacen', '[{"source": "https://www.livius.org/articles/place/madghacen/", "url": "https://www.livius.org/articles/place/madghacen/", "quote": "Madghacen (also known as Imedghassen, Medracen, and Madghis): royal tomb of an unknown Numidian king.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Medracen", "url": "https://en.wikipedia.org/wiki/Medracen", "quote": "It has been identified as a royal mausoleum built by the Berber Numidian Kingdom.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "Livius and Wikipedia describe the Medracen as a single royal tomb, a mausoleum built as a monumental tumulus; the most specific type is Tomb, not a necropolis complex.", "value_page": null}]'::jsonb),
    ('203fbf02-196b-4853-8504-d35a34085345'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Medracen', 'https://en.wikipedia.org/wiki/Madghacen', 'fields-wd1-2026-09-26b-s002-rollback:203fbf02-196b-4853-8504-d35a34085345:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Madghacen'' restored on Madghacen', '[{"source": "https://en.wikipedia.org/wiki/Medracen", "url": "https://en.wikipedia.org/wiki/Medracen", "quote": "Medracen is one of several large funerary monuments from the era of ancient Berber kingdoms in Classical antiquity.", "outcome": "found"}, {"source": "https://www.livius.org/articles/place/madghacen/", "url": "https://www.livius.org/articles/place/madghacen/", "quote": "Madghacen (also known as Imedghassen, Medracen, and Madghis): royal tomb of an unknown Numidian king.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect; the article''s own URL is Medracen, the English Wikipedia article on this mausoleum, which Livius confirms is the same monument (Madghacen = Medracen).", "value_page": {"lang": "en", "problem": null, "resolved_title": "Medracen", "unreadable": false, "wikibase_item": "Q1538575"}}]'::jsonb),
    ('2051a8ae-6ce5-4a33-bfa6-997ed2479750'::uuid, 'source_url', 'https://www.city.takasago.lg.jp/soshikikarasagasu/citypromotionshitsu/kanko_tokusan/1/1/3234.html', 'https://en.wikipedia.org/wiki/Ishi_no_H%C5%8Dden', 'fields-wd1-2026-09-26b-s002-rollback:2051a8ae-6ce5-4a33-bfa6-997ed2479750:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Ishi_no_H%C5%8Dden'' restored on Oushiko Shrine', '[{"source": "https://www.city.takasago.lg.jp/soshikikarasagasu/citypromotionshitsu/kanko_tokusan/1/1/3234.html", "url": "https://www.city.takasago.lg.jp/soshikikarasagasu/citypromotionshitsu/kanko_tokusan/1/1/3234.html", "quote": "Oushiko shrine is located near the Hoden stone quarry. In Oushiko Shrine, there is an enormous stone 5.7 meters high and 6.4 meters wide.", "outcome": "found"}, {"source": "https://www.mlit.go.jp/tagengo-db/en/R5-00215.html", "url": "https://www.mlit.go.jp/tagengo-db/en/R5-00215.html", "quote": "Records from the Edo period (1603–1867) show that Oushiko Jinja Shrine was visited by many influential people", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the Ishi no Hoden megalith (Q11584736), not the shrine; the shrine (Q11574829) has only a Japanese article, which does not print the name in Latin script, so Takasago City''s own English page on Oushiko Shrine is used, and the Japan Tourism Agency''s commentary names Oushiko Jinja Shrine too.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('2069e069-c994-46e2-b8b8-f8f8dd01abd0'::uuid, 'geom', 'SRID=4326;POINT(-6.526643 42.064137)', '0101000020E6100000C8441EB019221AC0794DA467B00A4540', 'fields-wd1-2026-09-26b-s002-rollback:2069e069-c994-46e2-b8b8-f8f8dd01abd0:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E6100000C8441EB019221AC0794DA467B00A4540'' restored on Peñas de la Cerca', '[{"source": "https://www.wikidata.org/wiki/Q16932312", "url": "https://www.wikidata.org/wiki/Q16932312", "quote": "42°3''50.89226\"N, 6°31''35.91502\"W", "outcome": "found"}, {"source": "https://www.openstreetmap.org/node/1241795777", "url": "https://www.openstreetmap.org/node/1241795777", "quote": "42.0639903, -6.5349952", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikidata places the hillfort at 42.0641 N, 6.5266 W, on the boundary between Palacios de Sanabria and Rosinos de la Requejada south of Rionegrito. OpenStreetMap''s Instituto Geográfico Nacional toponym ''Peñas de la Cerca'' lies 0.7 km from that point. The stored point is 2.2 km to the north, beyond the hamlet, so it is replaced.", "value_page": null}]'::jsonb),
