    ('2069e069-c994-46e2-b8b8-f8f8dd01abd0'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:2069e069-c994-46e2-b8b8-f8f8dd01abd0:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on Peñas de la Cerca', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2069e069-c994-46e2-b8b8-f8f8dd01abd0'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s002-rollback:2069e069-c994-46e2-b8b8-f8f8dd01abd0:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Peñas de la Cerca', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0132)", "decision": "clear", "status": "MISSING", "reasoning": "Only Wikipedia gives a date: it places the hillfort at the transition from the first to the second Iron Age, about the 7th century BC. The excavators'' project site and Celtiberia.net say only ''Iron Age'', and the excavation papers could not be read. With no second independent dated source, the field is emptied.", "value_page": null}]'::jsonb),
    ('20a18387-7871-456c-967a-c94abd69e3e0'::uuid, 'site_type', 'City', 'Underwater structures', 'fields-wd1-2026-09-26b-s002-rollback:20a18387-7871-456c-967a-c94abd69e3e0:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Underwater structures'' restored on Seuthopolis', '[{"source": "https://archaeologyinbulgaria.com/seuthopolis-koprinka-bulgaria/", "url": "https://archaeologyinbulgaria.com/seuthopolis-koprinka-bulgaria/", "quote": "The Ancient Thracian city of Seuthopolis (today under water) was established by King Seuthes III", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Seuthopolis", "url": "https://en.wikipedia.org/wiki/Seuthopolis", "quote": "Most of the space within the city was occupied not by homes but by official structures, the majority of the people living outside the city.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0014)", "decision": "replace", "status": "CONFLICT", "reasoning": "Archaeology in Bulgaria and Wikipedia both describe Seuthopolis as a city, the Odrysian royal capital; that its ruins now lie under the Koprinka Reservoir is its present state, not what the site is, so City replaces Underwater structures.", "value_page": null}]'::jsonb),
    ('21660e33-c3b7-462f-aaec-cbaded7b4a8d'::uuid, 'geom', 'SRID=4326;POINT(44.72166 41.83763)', '0101000020E610000006CA95A1545546401029457C87E84440', 'fields-wd1-2026-09-26b-s002-rollback:21660e33-c3b7-462f-aaec-cbaded7b4a8d:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E610000006CA95A1545546401029457C87E84440'' restored on Armazi', '[{"source": "https://es.wikipedia.org/wiki/Armazi", "url": "https://es.wikipedia.org/wiki/Armazi", "quote": "41.83763, 44.72166", "outcome": "found"}, {"source": "https://travelguide.ge/en/what-to-do/armaztsikhe-bagineti/", "url": "https://travelguide.ge/en/what-to-do/armaztsikhe-bagineti/", "quote": "Location 41.8383, 44.7211", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site''s main monument is the acropolis Armaztsikhe on Mount Bagineti opposite Mtskheta; the Spanish Wikipedia article and the TravelGuide.ge page for Armaztsikhe (Bagineti) both place it at about 41.838, 44.721 (OSM''s Armaztsikhe-Bagineti monument lies there too). The stored point is the rounded 41°49''N 44°40''E, about 5 km to the south-west in open hills, so it is replaced.", "value_page": null}]'::jsonb),
