    ('21660e33-c3b7-462f-aaec-cbaded7b4a8d'::uuid, 'lon', '44.72166', '44.66664523900913', 'fields-wd1-2026-09-26b-s002-rollback:21660e33-c3b7-462f-aaec-cbaded7b4a8d:lon', 'rollback of fields-wd1-2026-09-26b-s002: lon ''44.66664523900913'' restored on Armazi', '[{"source": "https://es.wikipedia.org/wiki/Armazi", "url": "https://es.wikipedia.org/wiki/Armazi", "quote": "41.83763, 44.72166", "outcome": "found"}, {"source": "https://travelguide.ge/en/what-to-do/armaztsikhe-bagineti/", "url": "https://travelguide.ge/en/what-to-do/armaztsikhe-bagineti/", "quote": "Location 41.8383, 44.7211", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "CONFLICT", "reasoning": "The site''s main monument is the acropolis Armaztsikhe on Mount Bagineti opposite Mtskheta; the Spanish Wikipedia article and the TravelGuide.ge page for Armaztsikhe (Bagineti) both place it at about 41.838, 44.721 (OSM''s Armaztsikhe-Bagineti monument lies there too). The stored point is the rounded 41°49''N 44°40''E, about 5 km to the south-west in open hills, so it is replaced.", "value_page": null}]'::jsonb),
    ('22aa305a-3ecf-454e-a643-3e08dbbd2e14'::uuid, 'period_name', '500 BC - 1 AD', '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:22aa305a-3ecf-454e-a643-3e08dbbd2e14:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on al-Siq', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-100) = ''500 BC - 1 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('22aa305a-3ecf-454e-a643-3e08dbbd2e14'::uuid, 'period_start', '-100', '1', 'fields-wd1-2026-09-26b-s002-rollback:22aa305a-3ecf-454e-a643-3e08dbbd2e14:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on al-Siq', '[{"source": "https://padc.pdtra.gov.jo/en/sitesdtls/16/The-Dam", "url": "https://padc.pdtra.gov.jo/en/sitesdtls/16/The-Dam", "quote": "Therefore, to control floodwaters, a dam was built across the mouth of the Siq in the 1st century BC, along with basins to hold water an 82-meter long rock-cut tunnel, which redirected water through Wadi Mudhlim to reservoirs, water cisterns and dams inside and outside Petra.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Siq", "url": "https://en.wikipedia.org/wiki/Siq", "quote": "The dam is a fairly true reconstruction of what the Nabataeans did to control Wadi Musa between the 1st century BC and the beginning of the 1st century AD.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0090)", "decision": "replace", "status": "MISSING", "reasoning": "The Siq itself is a natural fault; its history as an archaeological site begins with the Nabataean works in it, which the Petra authority dates to the 1st century BC (dam and tunnel at its mouth) and Wikipedia to between the 1st century BC and the early 1st century AD - the 500 BC - 1 AD bucket, not the stored 1 - 500 AD.", "value_page": null}]'::jsonb),
    ('22aa305a-3ecf-454e-a643-3e08dbbd2e14'::uuid, 'site_type', 'Natural feature', 'Archaeological site', 'fields-wd1-2026-09-26b-s002-rollback:22aa305a-3ecf-454e-a643-3e08dbbd2e14:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Archaeological site'' restored on al-Siq', '[{"source": "https://en.wikipedia.org/wiki/Siq", "url": "https://en.wikipedia.org/wiki/Siq", "quote": "the Siq is a natural geological fault split apart by tectonic forces", "outcome": "found"}, {"source": "https://pdtra.gov.jo/EN/ListDetails/Historical_Location/1234/1", "url": "https://pdtra.gov.jo/EN/ListDetails/Historical_Location/1234/1", "quote": "The Nabataeans skillfully utilized and enhanced this unique natural feature, transforming it into a secure and protected entrance to their city.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Siq is the gorge entrance to Petra: English Wikipedia says it is a natural geological fault split apart by tectonic forces, and the Petra Development and Tourism Regional Authority calls it a unique natural feature that the Nabataeans enhanced into the city''s entrance; it is a natural gorge, not a built structure, so Natural feature is more specific than the generic Archaeological site.", "value_page": null}]'::jsonb),
    ('23286e8a-3777-4e5f-b554-33c75c736633'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Wari_(archaeological_site)', 'https://en.wikipedia.org/wiki/Huari_(archaeological_site)', 'fields-wd1-2026-09-26b-s002-rollback:23286e8a-3777-4e5f-b554-33c75c736633:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Huari_(archaeological_site)'' restored on Huari Archaeological Site', '[{"source": "https://en.wikipedia.org/wiki/Wari_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/Wari_(archaeological_site)", "quote": "or Huari", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Wari_(archaeological_site)", "url": "https://en.wikipedia.org/wiki/Wari_(archaeological_site)", "quote": "is an archaeological site located near the town of Quinua", "outcome": "found"}, {"source": "http://whowaswhowari.sdsu.edu/1979HuarpaNPms4Web.html", "url": "http://whowaswhowari.sdsu.edu/1979HuarpaNPms4Web.html", "quote": "Huari is the name given to a prehistoric site located 10 km. north of Ayacucho along the road to the town of Quinua.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0109)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Huari_(archaeological_site) URL is only a redirect to the English Wikipedia article Wari (archaeological site), the site''s own article, which opens ''Wari or Huari is an archaeological site located near the town of Quinua''; Knobloch''s Huari excavation report names the same site near Quinua, so the direct article URL replaces the redirect.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Wari (archaeological site)", "unreadable": false, "wikibase_item": "Q3395231"}}]'::jsonb),
    ('241df2d5-69c9-47e0-9df3-105a26a4d141'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:241df2d5-69c9-47e0-9df3-105a26a4d141:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on Carl Wark', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('241df2d5-69c9-47e0-9df3-105a26a4d141'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s002-rollback:241df2d5-69c9-47e0-9df3-105a26a4d141:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Carl Wark', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "clear", "status": "MISSING", "reasoning": "Wikipedia says the date of construction ''remains unknown'' (Iron Age postulated, Early Medieval from the 1950 excavation, possibly Neolithic use) and the National Trust record gives both a Dark Age and an Iron Age dating; no securely attested start exists, so the stored -1500 cannot be sourced.", "value_page": null}]'::jsonb),
    ('241df2d5-69c9-47e0-9df3-105a26a4d141'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:241df2d5-69c9-47e0-9df3-105a26a4d141:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Carl Wark', '[{"source": "https://en.wikipedia.org/wiki/Carl_Wark", "url": "https://en.wikipedia.org/wiki/Carl_Wark", "quote": "The cliffs and embankment form an enclosure that has been interpreted as an Iron Age hill fort, though the date of construction and purpose of the fortifications remains unknown.", "outcome": "found"}, {"source": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA113035", "url": "https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA113035", "quote": "Carl Wark hill fort occupies the summit of a high rocky plateau.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0030)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the National Trust heritage record both describe Carl Wark as a hill fort; Fort is the most specific canonical type for a hillfort, rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('24695f34-5605-4cdd-965f-fd646c1ed044'::uuid, 'site_type', 'Megalithic structures', 'Megalithic stones', 'fields-wd1-2026-09-26b-s002-rollback:24695f34-5605-4cdd-965f-fd646c1ed044:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic stones'' restored on Ahu Vinapu', '[{"source": "https://imaginarapanui.com/en/easter-island-sightseeing/easter-island-archaeology/vinapu/", "url": "https://imaginarapanui.com/en/easter-island-sightseeing/easter-island-archaeology/vinapu/", "quote": "Vinapu, a great megalithic work", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Ahu_Vinapu", "url": "https://en.wikipedia.org/wiki/Ahu_Vinapu", "quote": "The ceremonial center of Vinapu includes one of the larger ahu on Rapa Nui. The ahu exhibits extraordinary stonemasonry consisting of large, carefully fitted slabs of basalt.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0016)", "decision": "replace", "status": "CONFLICT", "reasoning": "Ahu Vinapu is a ceremonial complex of ahu, stone platforms faced with large fitted basalt slabs; Imagina Rapa Nui calls it a great megalithic work and Wikipedia describes the ahu built of large fitted basalt slabs. The site is a built megalithic platform complex, so Megalithic structures fits better than loose Megalithic stones.", "value_page": null}]'::jsonb),
    ('251ac618-a557-4c31-9129-65afc47b649d'::uuid, 'site_type', 'City', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:251ac618-a557-4c31-9129-65afc47b649d:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Sybaris on the Traeis', '[{"source": "https://en.wikipedia.org/wiki/Sybaris_on_the_Traeis", "url": "https://en.wikipedia.org/wiki/Sybaris_on_the_Traeis", "quote": "Sybaris on the Traeis was an ancient city situated on the Traeis river", "outcome": "found"}, {"source": "https://www.treccani.it/enciclopedia/sibari-sul-traente_%28Enciclopedia-Italiana%29/", "url": "https://www.treccani.it/enciclopedia/sibari-sul-traente_%28Enciclopedia-Italiana%29/", "quote": "La nuova Sibari rimase sempre una città di secondaria importanza", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0088)", "decision": "replace", "status": "MISSING", "reasoning": "Both Wikipedia and Treccani describe Sybaris on the Traeis as a city (a Greek colony and member of the Achaean league with Croton and Caulonia), so City is the most specific type the sources support.", "value_page": null}]'::jsonb),
    ('257ce429-7d0c-4444-8ed5-57d129c25d50'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:257ce429-7d0c-4444-8ed5-57d129c25d50:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on Schanzenkopf - Schwedenschanze', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('257ce429-7d0c-4444-8ed5-57d129c25d50'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s002-rollback:257ce429-7d0c-4444-8ed5-57d129c25d50:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Schanzenkopf - Schwedenschanze', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "clear", "status": "MISSING", "reasoning": "The Hallstatt date (800-400 BC) repeated by German Wikipedia, the Spessart project board and alleburgen.de is explicitly a conjecture without archaeological evidence, while the Bavarian monument list records only finds of the later La Tène period and fabuly dates it c. 150 BC from stray sherds; no two independent sources securely date the start, so the field is emptied.", "value_page": null}]'::jsonb),
    ('257ce429-7d0c-4444-8ed5-57d129c25d50'::uuid, 'site_type', 'Fort', 'Earthwork', 'fields-wd1-2026-09-26b-s002-rollback:257ce429-7d0c-4444-8ed5-57d129c25d50:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Earthwork'' restored on Schanzenkopf - Schwedenschanze', '[{"source": "https://www.wikidata.org/wiki/Q98160450", "url": "https://www.wikidata.org/wiki/Q98160450", "quote": "promontory fort", "outcome": "found"}, {"source": "https://www.alleburgen.de/bd.php?id=3126", "url": "https://www.alleburgen.de/bd.php?id=3126", "quote": "vorgeschichtliche Abschnittsbefestigung vermutlich aus der Hallstattzeit mit Hauptwall und vorgelagerten Graben", "outcome": "found"}, {"source": "https://www.fabuly.de/eintrag/detail/ringwall-schwedenschanze-362", "url": "https://www.fabuly.de/eintrag/detail/ringwall-schwedenschanze-362", "quote": "Auf dem zwischen Michelbach und Niedersteinbach gelegenen Schanzenkopf befindet sich eine vorgeschichtliche, 2,8 ha große Befestigung", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The heritage item classes the Schwedenschanze as a promontory fort (Abschnittsbefestigung), and alleburgen.de and fabuly describe a prehistoric fortified spur with main rampart, ditch and outer rampart; Fort is more specific than the generic Earthwork.", "value_page": null}]'::jsonb),
    ('257ce429-7d0c-4444-8ed5-57d129c25d50'::uuid, 'source_url', 'https://www.alleburgen.de/bd.php?id=3126', 'https://en.wikipedia.org/wiki/Schanzenkopf_(Schwedenschanze)', 'fields-wd1-2026-09-26b-s002-rollback:257ce429-7d0c-4444-8ed5-57d129c25d50:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Schanzenkopf_(Schwedenschanze)'' restored on Schanzenkopf - Schwedenschanze', '[{"source": "https://www.alleburgen.de/bd.php?id=3126", "url": "https://www.alleburgen.de/bd.php?id=3126", "quote": "Schwedenschanze Wallburgrest in Alzenau-Michelbach", "outcome": "found"}, {"source": "https://www.fabuly.de/eintrag/detail/ringwall-schwedenschanze-362", "url": "https://www.fabuly.de/eintrag/detail/ringwall-schwedenschanze-362", "quote": "Ringwall Schwedenschanze", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0059)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article is about the hill Schanzenkopf; the fort has no Wikipedia article of its own, and alleburgen.de has a dedicated entry for the Schwedenschanze rampart on the Schanzenkopf spur near Michelbach, which fabuly''s entry on the Ringwall Schwedenschanze confirms.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('269e2820-acf1-4974-b75f-3c0460482ade'::uuid, 'site_type', 'Temple', 'Temple complex', 'fields-wd1-2026-09-26b-s002-rollback:269e2820-acf1-4974-b75f-3c0460482ade:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Temple complex'' restored on Duraz Temple', '[{"source": "https://culture.gov.bh/en/visitingbahrain/CulturalTourism/Destinations/Name,10346,en.php", "url": "https://culture.gov.bh/en/visitingbahrain/CulturalTourism/Destinations/Name,10346,en.php", "quote": "This area has revealed a temple from the Dilmun period, probably built in the early 2nd millennium BCE.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Diraz_Temple", "url": "https://en.wikipedia.org/wiki/Diraz_Temple", "quote": "Diraz Temple dates to circa 3rd millennium BCE based on the recovered artifacts from the site", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0009)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe a single Dilmun temple (a columned hall with a cella and altar) in the remnant of the Diraz settlement, not a complex of several temples, so the specific type Temple replaces Temple complex.", "value_page": null}]'::jsonb),
    ('274600b9-31f5-45ce-96da-b0f326977dd5'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:274600b9-31f5-45ce-96da-b0f326977dd5:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Knin', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('274600b9-31f5-45ce-96da-b0f326977dd5'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s002-rollback:274600b9-31f5-45ce-96da-b0f326977dd5:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Knin', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0017)", "decision": "clear", "status": "MISSING", "reasoning": "The sources date the first occupation only by period and disagree on it: English Wikipedia says the Spas hill has been inhabited since the Stone Age, the Hrvatska enciklopedija since the Neolithic, and the City of Knin continuously from the Eneolithic; none gives the site a year, century or millennium, and the stored 500 BC is later than all of them, so the field is emptied.", "value_page": null}]'::jsonb),
    ('277970ce-65f8-403a-8e20-dbcadac0f214'::uuid, 'period_name', NULL, '< 4500 BC', 'fields-wd1-2026-09-26b-s002-rollback:277970ce-65f8-403a-8e20-dbcadac0f214:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''< 4500 BC'' restored on Eston Nab', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('277970ce-65f8-403a-8e20-dbcadac0f214'::uuid, 'period_start', NULL, '-6000', 'fields-wd1-2026-09-26b-s002-rollback:277970ce-65f8-403a-8e20-dbcadac0f214:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-6000'' restored on Eston Nab', '[{"source": "WD1 decision (counted, round 2, wd1-r2-b0001)", "decision": "clear", "status": "MISSING", "reasoning": "The stored -6000 rests only on Wikipedia''s ''flint arrowheads, possibly 6000 to 4000 BC'' from the hill, which are stray finds and not the site; the site''s own start is dated by one source family only (Tees Archaeology, echoed by Wikipedia: first palisaded enclosures ''around 700 BC''), while Historic England, the Atlas of Hillforts and the North East Research Framework give only period names for it (first activity Early Bronze Age barrow, hilltop first enclosed by palisades in the Late Bronze Age, ditch and rampart in the early 5th century BC), so no two independent readable sources date one start year and the field is left empty.", "value_page": null}]'::jsonb),
    ('277970ce-65f8-403a-8e20-dbcadac0f214'::uuid, 'site_type', 'Fort', 'Mound/tumulus', 'fields-wd1-2026-09-26b-s002-rollback:277970ce-65f8-403a-8e20-dbcadac0f214:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Mound/tumulus'' restored on Eston Nab', '[{"source": "https://en.wikipedia.org/wiki/Eston_Nab", "url": "https://en.wikipedia.org/wiki/Eston_Nab", "quote": "It is the site of Bronze Age burial mounds and an Iron Age hill fort.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=5137", "url": "https://www.megalithic.co.uk/article.php?sid=5137", "quote": "The earliest phase of this univallate hillfort dates back to the Late Bronze Age when a palisade enclosure was erected here.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0034)", "decision": "replace", "status": "CONFLICT", "reasoning": "The monument on the Nab is a palisaded enclosure succeeded by a univallate hill fort (Wikipedia, Megalithic Portal, scheduled as ''Eston Nab hill fort, palisaded settlement and beacon''); the Bronze Age barrows lie 100 m to the south and are a separate monument, so Fort replaces Mound/tumulus.", "value_page": null}]'::jsonb),
    ('27f27e7e-4224-4378-b0d2-ef22f88bd725'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:27f27e7e-4224-4378-b0d2-ef22f88bd725:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Monte Adranone', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-600) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('27f27e7e-4224-4378-b0d2-ef22f88bd725'::uuid, 'period_start', '-600', '-500', 'fields-wd1-2026-09-26b-s002-rollback:27f27e7e-4224-4378-b0d2-ef22f88bd725:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Monte Adranone', '[{"source": "https://romanhistory.net/encyclopedia-of-southern-italy/adranon/", "url": "https://romanhistory.net/encyclopedia-of-southern-italy/adranon/", "quote": "Excavations, begun in 1968, have revealed the remains on a Greek colony established here in the 6th century BC probably established by Selinunte (Selinus).", "outcome": "found"}, {"source": "https://siciliasacra.net/scopri/path-and-themes/archaeological-area-of-monte-adranone/?lang=en", "url": "https://siciliasacra.net/scopri/path-and-themes/archaeological-area-of-monte-adranone/?lang=en", "quote": "the ancient Adranon that was colonized by Selinunte in the 6th century BC and conquered by Carthage in the 4th century BC", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0086)", "decision": "replace", "status": "MISSING", "reasoning": "The Encyclopedia of Southern Italy says excavations revealed a Greek colony established on Monte Adranone in the 6th century BC, and Sicilia Sacra likewise dates the Selinuntine colonisation of Adranon to the 6th century BC (the Enciclopedia dell''Arte Antica puts the first city walls at the end of that century); the securely dated start is the 6th century BC (-600), in the 1500 - 500 BC bucket, not the stored 500 BC - 1 AD.", "value_page": null}]'::jsonb),
    ('27fd971a-5ea6-42d0-94db-e4a45523f016'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:27fd971a-5ea6-42d0-94db-e4a45523f016:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Muyu Urqu', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('27fd971a-5ea6-42d0-94db-e4a45523f016'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s002-rollback:27fd971a-5ea6-42d0-94db-e4a45523f016:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Muyu Urqu', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0112)", "decision": "clear", "status": "MISSING", "reasoning": "The excavator (Zapata 1998) and later work place Muyu Urqu''s terraced hill and sunken court in the Middle and Late Formative Period, with later Middle Horizon and Inca use, but no source gives a year or century for the start of the site itself; the stored 1 AD is unsupported, so the field is emptied.", "value_page": null}]'::jsonb),
    ('27fd971a-5ea6-42d0-94db-e4a45523f016'::uuid, 'site_type', 'Sacred site', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:27fd971a-5ea6-42d0-94db-e4a45523f016:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Muyu Urqu', '[{"source": "https://repositorio.pucp.edu.pe/items/c6f1303a-7b04-4322-837a-94cbd7f3693f", "url": "https://repositorio.pucp.edu.pe/items/c6f1303a-7b04-4322-837a-94cbd7f3693f", "quote": "The excavations at Batan Urqu and Muyu Urqu revealed the existence of sunken courts as part of an ideological-religious system with sacred mountains as connection points, as part of a cognitive map.", "outcome": "found"}, {"source": "https://elmerolorteguiramirez.blogspot.com/2025/05/cultura-chanapata-cusco-segunda-parte.html", "url": "https://elmerolorteguiramirez.blogspot.com/2025/05/cultura-chanapata-cusco-segunda-parte.html", "quote": "Muyu Orqo, un conjunto de plataformas artificiales de círculos concéntricos que en su cúspide tiene una extensa plaza hundida rectangular, vestigio de un culto altiplánico", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0112)", "decision": "replace", "status": "CONFLICT", "reasoning": "The excavator describes Muyu Urqu as a sacred hill transformed with concentric terraces and a sunken court on its summit, a node of a Formative religious system, and later summaries repeat it as ceremonial architecture of an altiplano cult; nothing calls it a town, so the stored ''City/town/settlement'' is replaced by the sacred-site type.", "value_page": null}]'::jsonb),
    ('28a8e565-a9c1-4a1d-90ee-d889b0c372db'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:28a8e565-a9c1-4a1d-90ee-d889b0c372db:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on Odysseus Palace', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('28a8e565-a9c1-4a1d-90ee-d889b0c372db'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s002-rollback:28a8e565-a9c1-4a1d-90ee-d889b0c372db:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Odysseus Palace', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0010)", "decision": "clear", "status": "MISSING", "reasoning": "The site at Agios Athanasios (''School of Homer'', Ithaca) is dated inconsistently: the 2025 Ministry of Culture announcement (repeated by news outlets, so one source family) reports human activity from the Final Neolithic and Mycenaean palatial remains of the 14th-13th century BC, a tourist guide puts the earliest occupation in the Middle Helladic (1900-1600 BC), and Pleiades only says Bronze Age and Iron Age phases; no two independent sources give the same start, so the stored -1500 cannot be confirmed.", "value_page": null}]'::jsonb),
    ('28a8e565-a9c1-4a1d-90ee-d889b0c372db'::uuid, 'site_type', 'Palace', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s002-rollback:28a8e565-a9c1-4a1d-90ee-d889b0c372db:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Necropolis/tombs complex'' restored on Odysseus Palace', '[{"source": "https://www.aegeussociety.org/en/news/greek-archeologist-discovers-palace-of-odysseus-in-ithaca/", "url": "https://www.aegeussociety.org/en/news/greek-archeologist-discovers-palace-of-odysseus-in-ithaca/", "quote": "Thanasis Papadopoulos, who has been carrying out excavations on the Greek hero’s home island for 16 years, said he had discovered the remains of a three-storey palace and a well, which date back to the 13th century BC", "outcome": "found"}, {"source": "https://www.ithaca.org.au/odysseus-palace-1", "url": "https://www.ithaca.org.au/odysseus-palace-1", "quote": "The excavation site is believed to be a large Mycenaean palatial building complex occupying two levels.", "outcome": "found"}, {"source": "https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1", "url": "https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1", "quote": "Το Ανάκτορο του Οδυσσέα είναι αρχαιολογικός τόπος μυκηναϊκού ανακτόρου στο νησί της Ιθάκης, στην Ελλάδα.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "MISSING", "reasoning": "The site is described by the Aegeus Society, the Ithacan Philanthropic Society and Greek Wikipedia as a Mycenaean palace or palatial complex; it is not a necropolis (rock-cut graves are only one minor feature), so the type becomes Palace.", "value_page": null}]'::jsonb),
    ('28a8e565-a9c1-4a1d-90ee-d889b0c372db'::uuid, 'source_url', 'https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1', 'https://ithaca.org.au/about-ithaca/odysseus-palace', 'fields-wd1-2026-09-26b-s002-rollback:28a8e565-a9c1-4a1d-90ee-d889b0c372db:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://ithaca.org.au/about-ithaca/odysseus-palace'' restored on Odysseus Palace', '[{"source": "https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1", "url": "https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1", "quote": "Photos of the Palace of Odysseus at Ithaca", "outcome": "found"}, {"source": "https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1", "url": "https://el.wikipedia.org/wiki/%CE%91%CE%BD%CE%AC%CE%BA%CF%84%CE%BF%CF%81%CE%BF_%CF%84%CE%BF%CF%85_%CE%9F%CE%B4%CF%85%CF%83%CF%83%CE%AD%CE%B1", "quote": "Η συγκεκριμένη τοποθεσία είναι επίσης γνωστή ως Σχολή Ομήρου, καθώς και ως Άγιος Αθανάσιος.", "outcome": "found"}, {"source": "https://www.ithaca.org.au/odysseus-palace-1", "url": "https://www.ithaca.org.au/odysseus-palace-1", "quote": "Excavations at the archaeological site believed to be the Palace of Homer’s epic hero Odysseus on the island of Ithaca are to resume after the Prime Minister promised the necessary funding.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0069)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Ithacan Philanthropic Society URL returns 404 (its text moved to /odysseus-palace-1); there is no English Wikipedia article on the site, and the Greek Wikipedia article ''Ανάκτορο του Οδυσσέα'' (Palace of Odysseus, also called School of Homer / Agios Athanasios) is the site''s own article, so it becomes the source.", "value_page": {"lang": "el", "problem": null, "resolved_title": "Ανάκτορο του Οδυσσέα", "unreadable": false, "wikibase_item": "Q22681567"}}]'::jsonb),
    ('28fbf63d-5ca4-45fd-a54e-7a660232b148'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:28fbf63d-5ca4-45fd-a54e-7a660232b148:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on KaʼKabish', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('28fbf63d-5ca4-45fd-a54e-7a660232b148'::uuid, 'period_start', '-800', '-500', 'fields-wd1-2026-09-26b-s002-rollback:28fbf63d-5ca4-45fd-a54e-7a660232b148:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on KaʼKabish', '[{"source": "http://www.kakabish.org/index.html", "url": "http://www.kakabish.org/index.html", "quote": "Settled around 800 BC, the city survived three political upheavals, before finally ceasing to exist around AD 1500.", "outcome": "found"}, {"source": "https://caribbeanlifestyle.com/dental-research-trent-university-ancient-belize-life/", "url": "https://caribbeanlifestyle.com/dental-research-trent-university-ancient-belize-life/", "quote": "Ka’Kabish was a thriving city that was founded in 800-600 BC and lasted almost 1800 years.", "outcome": "found"}, {"source": "WD1 decision (counted, round 1, wd1-r1-b0003)", "decision": "replace", "status": "MISSING", "reasoning": "The Ka''Kabish Archaeological Research Project (Orange Walk District, Belize) states the city was settled around 800 BC, and an independent news report on the Trent University research dates its founding to 800-600 BC; the Middle Formative start (c. 800 BC) lies in the 1500 - 500 BC bucket, not the stored 500 BC - 1 AD bucket, so the value is replaced.", "value_page": null}]'::jsonb),
    ('28fbf63d-5ca4-45fd-a54e-7a660232b148'::uuid, 'site_type', 'City', 'Temple complex', 'fields-wd1-2026-09-26b-s002-rollback:28fbf63d-5ca4-45fd-a54e-7a660232b148:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Temple complex'' restored on KaʼKabish', '[{"source": "https://en.wikipedia.org/wiki/Ka%CA%BCKabish", "url": "https://en.wikipedia.org/wiki/Ka%CA%BCKabish", "quote": "It was once a moderate sized city, built as part of the Maya civilization,", "outcome": "found"}, {"source": "https://www.kakabish.org/index.html", "url": "https://www.kakabish.org/index.html", "quote": "Ka''kabish is an ancient Maya city located in North-Central Belize. Settled around 800 BC, the city survived three political upheavals, before finally ceasing to exist around AD 1500.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0011)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and the Ka''kabish Archaeological Research Project both describe Ka''Kabish as an ancient Maya city (with two temples, a ball court, elite platforms and 90+ structures), not merely a temple complex, so the type is City.", "value_page": null}]'::jsonb),
    ('290410a4-c7ed-4fe7-842d-bfe7ab97e899'::uuid, 'geom', 'SRID=4326;POINT(-112.51282 33.58664)', '0101000020E6100000356D6B5318235CC0319C5B5753CB4040', 'fields-wd1-2026-09-26b-s002-rollback:290410a4-c7ed-4fe7-842d-bfe7ab97e899:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E6100000356D6B5318235CC0319C5B5753CB4040'' restored on White Tank Mountain Regional Park', '[{"source": "https://www.megalithic.co.uk/article.php?sid=14700", "url": "https://www.megalithic.co.uk/article.php?sid=14700", "quote": "Latitude: 33.586530N Longitude: 112.51265W", "outcome": "found"}, {"source": "https://www.fotospot.com/attractions/arizona/white-tank-petroglyph-plaza", "url": "https://www.fotospot.com/attractions/arizona/white-tank-petroglyph-plaza", "quote": "33.586697, -112.512513", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0150)", "decision": "replace", "status": "CONFLICT", "reasoning": "The park''s main rock-art site is Petroglyph Plaza on the Waterfall Canyon Trail, which Maricopa County names as the largest concentration of rock art; the Megalithic Portal (whose location is given for Petroglyph Plaza) and Fotospot''s entry for White Tank Petroglyph Plaza both place it about 3.3 km east of the stored point, which lies in the mountains west of the site.", "value_page": null}]'::jsonb),
    ('290410a4-c7ed-4fe7-842d-bfe7ab97e899'::uuid, 'lat', '33.58664', '33.588480872851854', 'fields-wd1-2026-09-26b-s002-rollback:290410a4-c7ed-4fe7-842d-bfe7ab97e899:lat', 'rollback of fields-wd1-2026-09-26b-s002: lat ''33.588480872851854'' restored on White Tank Mountain Regional Park', '[{"source": "https://www.megalithic.co.uk/article.php?sid=14700", "url": "https://www.megalithic.co.uk/article.php?sid=14700", "quote": "Latitude: 33.586530N Longitude: 112.51265W", "outcome": "found"}, {"source": "https://www.fotospot.com/attractions/arizona/white-tank-petroglyph-plaza", "url": "https://www.fotospot.com/attractions/arizona/white-tank-petroglyph-plaza", "quote": "33.586697, -112.512513", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0150)", "decision": "replace", "status": "CONFLICT", "reasoning": "The park''s main rock-art site is Petroglyph Plaza on the Waterfall Canyon Trail, which Maricopa County names as the largest concentration of rock art; the Megalithic Portal (whose location is given for Petroglyph Plaza) and Fotospot''s entry for White Tank Petroglyph Plaza both place it about 3.3 km east of the stored point, which lies in the mountains west of the site.", "value_page": null}]'::jsonb),
