    ('290410a4-c7ed-4fe7-842d-bfe7ab97e899'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=14700', 'https://en.wikipedia.org/wiki/White_Tank_Mountain_Regional_Park', 'fields-wd1-2026-09-26b-s002-rollback:290410a4-c7ed-4fe7-842d-bfe7ab97e899:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/White_Tank_Mountain_Regional_Park'' restored on White Tank Mountain Regional Park', '[{"source": "https://www.megalithic.co.uk/article.php?sid=14700", "url": "https://www.megalithic.co.uk/article.php?sid=14700", "quote": "Site Name: White Tank Mountains Petroglyphs", "outcome": "found"}, {"source": "https://www.maricopacountyparks.net/park-locator/white-tank-mountain-regional-park/park-information/history/", "url": "https://www.maricopacountyparks.net/park-locator/white-tank-mountain-regional-park/park-information/history/", "quote": "Waterfall Canyon Trail (Petroglyph Plaza) – the largest concentration of rock art", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0150)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the regional park as a recreation area; the Megalithic Portal entry is about the White Tank Mountains petroglyphs themselves (located at Petroglyph Plaza), which Maricopa County Parks also names as the park''s main rock-art site.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('2910c599-c631-4c92-a342-75be81adb95a'::uuid, 'site_type', 'Gate', 'Gate/archway/bridge', 'fields-wd1-2026-09-26b-s002-rollback:2910c599-c631-4c92-a342-75be81adb95a:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Gate/archway/bridge'' restored on Aldersgate', '[{"source": "https://www.thehistoryoflondon.co.uk/aldersgate/", "url": "https://www.thehistoryoflondon.co.uk/aldersgate/", "quote": "Aldersgate was a London gate on the north-west of the city that originated in the Roman period.", "outcome": "found"}, {"source": "https://mapoflondon.uvic.ca/ALDE3.htm", "url": "https://mapoflondon.uvic.ca/ALDE3.htm", "quote": "The gate was likely built into the Wall of London during the Roman Conquest, marking the northern entrance into the city.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "The History of London and the University of Victoria''s Map of Early Modern London both describe Aldersgate as a city gate in London Wall. Gate is the specific canonical type; it was neither an archway nor a bridge.", "value_page": null}]'::jsonb),
    ('2910c599-c631-4c92-a342-75be81adb95a'::uuid, 'source_url', 'https://mapoflondon.uvic.ca/ALDE3.htm', 'https://en.wikipedia.org/wiki/Aldersgate', 'fields-wd1-2026-09-26b-s002-rollback:2910c599-c631-4c92-a342-75be81adb95a:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Aldersgate'' restored on Aldersgate', '[{"source": "https://mapoflondon.uvic.ca/ALDE3.htm", "url": "https://mapoflondon.uvic.ca/ALDE3.htm", "quote": "The ensuing reconstruction project was completed in 1618 at the expense of a legacy left by William Parker for the express purpose of rebuilding Aldersgate", "outcome": "found"}, {"source": "https://www.thehistoryoflondon.co.uk/aldersgate/", "url": "https://www.thehistoryoflondon.co.uk/aldersgate/", "quote": "Aldersgate was a London gate on the north-west of the city that originated in the Roman period.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0025)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the modern ward of the City of London, and the gate has no article of its own. The Map of Early Modern London (University of Victoria) has a scholarly encyclopedia entry on the gate Aldersgate itself, and The History of London independently describes the same gate.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
