    ('29446177-8f7d-4e23-9a9c-6c9ba2959472'::uuid, 'site_type', 'Cairn', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:29446177-8f7d-4e23-9a9c-6c9ba2959472:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Rubha an Dùnain Passage Grave', '[{"source": "https://her.highland.gov.uk/Monument/MHG4901", "url": "https://her.highland.gov.uk/Monument/MHG4901", "quote": "A Hebridean-type round chambered cairn with a polygonal chamber, antechamber and short passage.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=23096", "url": "https://www.megalithic.co.uk/article.php?sid=23096", "quote": "Near the northwest shore of Loch na h-Airde on the Rubh'' an Dunain peninsula stands the remains of a Neolithic chambered cairn.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Highland HER and the Megalithic Portal both describe the monument as a chambered cairn (a passage tomb), not a settlement, so the type is Cairn.", "value_page": null}]'::jsonb),
