    ('2990f219-d421-4474-b478-6b9b0f81990b'::uuid, 'period_start', '1', '-500', 'fields-wd1-2026-09-26b-s002-rollback:2990f219-d421-4474-b478-6b9b0f81990b:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Villa Romana de Río Verde', '[{"source": "https://andaluciarustica.com/en/roman-villa-of-rio-verde-marbella.htm", "url": "https://andaluciarustica.com/en/roman-villa-of-rio-verde-marbella.htm", "quote": "The villa was built between the late 1st century and the early 2nd century AD.", "outcome": "found"}, {"source": "https://viatorimperi.es/marbella/", "url": "https://viatorimperi.es/marbella/", "quote": "La villa se construyó a finales del siglo I d.C. o principios del II d.C.", "outcome": "found"}, {"source": "https://n-340.org/patrimonio/items-patrimoniales/malaga/marbella/villa-romana-de-rio-verde/", "url": "https://n-340.org/patrimonio/items-patrimoniales/malaga/marbella/villa-romana-de-rio-verde/", "quote": "El desarrollo y esplendor de la misma fue fechado por sus descubridores, entre principios del siglo I y comienzos del II de nuestra era", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0135)", "decision": "replace", "status": "MISSING", "reasoning": "Andalucía Rústica, Viator Imperi and the N-340 inventory date the villa''s construction to the 1st century AD (late 1st to early 2nd century), so the start is the 1st century AD (year 1), in the 1 - 500 AD bucket, not the stored 500 BC.", "value_page": null}]'::jsonb),
    ('29b7554d-b821-4aa7-b1de-958cd9398b65'::uuid, 'source_url', 'https://archiqoo.com/locations/ksar_lalla_fatma.php', 'https://jazairhope-org.translate.goog/fr/ksar-lalla-fatma-ou-la-belle-au-bois-dormant/?_x_tr_sl=fr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc', 'fields-wd1-2026-09-26b-s002-rollback:29b7554d-b821-4aa7-b1de-958cd9398b65:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://jazairhope-org.translate.goog/fr/ksar-lalla-fatma-ou-la-belle-au-bois-dormant/?_x_tr_sl=fr&_x_tr_tl=en&_x_tr_hl=en&_x_tr_pto=sc'' restored on Ksar Lalla Fatma', '[{"source": "https://archiqoo.com/locations/ksar_lalla_fatma.php", "url": "https://archiqoo.com/locations/ksar_lalla_fatma.php", "quote": "Ksar Lalla Fatma is a historical Roman site located in Oued El Djenane in El Taref Province, east of Algeria.", "outcome": "found"}, {"source": "https://lasentinelle.dz/index.php/2024/01/06/ksar-lalla-fatma-a-el-tarf-un-site-archeologique-classe-au-patrimoine-national-protege/", "url": "https://lasentinelle.dz/index.php/2024/01/06/ksar-lalla-fatma-a-el-tarf-un-site-archeologique-classe-au-patrimoine-national-protege/", "quote": "Le ministère de la Culture et des Arts vient d’approuver le classement de Ksar Lalla Fatma, situé dans une forêt de chêne-liège à Oued Djenane, dans la commune d’El Aioun (40 km à l’Est d’El Tarf), en tant que site archéologique national protégé, affirmé, jeudi, le directeur de la culture et des arts, Abdelkader Azzedine.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a Google Translate proxy of a blog post; no Wikipedia article exists, and Archiqoo''s heritage entry is a plain-HTML page devoted to this very site, confirmed by the La Sentinelle report on its classification.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
