    ('2a262303-2cf1-4f9a-97d7-e8a7fc194530'::uuid, 'period_start', '-200', '-1500', 'fields-wd1-2026-09-26b-s002-rollback:2a262303-2cf1-4f9a-97d7-e8a7fc194530:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Alabanda Amfi Tiyatro Tarihi Alanı', '[{"source": "https://www.aeternitas-numismatics.com/single-post/alabanda-history-and-coinage", "url": "https://www.aeternitas-numismatics.com/single-post/alabanda-history-and-coinage", "quote": "Photo 7.- General view of the cavea of the Alabanda theater, with its two levels. 2nd Century BC.", "outcome": "found"}, {"source": "https://ancienttheatrescom.wpcomstaging.com/theatre/alabanda/", "url": "https://ancienttheatrescom.wpcomstaging.com/theatre/alabanda/", "quote": "constructed during the Hellenistic period (c. 250-150 BCE) with subsequent Roman-era modifications", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0140)", "decision": "replace", "status": "MISSING", "reasoning": "The site is the theatre of Alabanda, not the city: Aeternitas Numismatics dates the theatre to the 2nd century BC and the Ancient Theatre Archive dates its construction to the Hellenistic period, c. 250-150 BCE; both put the start in the 500 BC - 1 AD bucket, not in the stored 1500 - 500 BC bucket (which was the city''s date), so it is the 2nd century BC, -200.", "value_page": null}]'::jsonb),
    ('2a262303-2cf1-4f9a-97d7-e8a7fc194530'::uuid, 'source_url', 'https://kulturenvanteri.com/en/yer/alabanda-antik-tiyatrosu/', 'https://en.wikipedia.org/wiki/Alabanda', 'fields-wd1-2026-09-26b-s002-rollback:2a262303-2cf1-4f9a-97d7-e8a7fc194530:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Alabanda'' restored on Alabanda Amfi Tiyatro Tarihi Alanı', '[{"source": "https://kulturenvanteri.com/en/yer/alabanda-antik-tiyatrosu/", "url": "https://kulturenvanteri.com/en/yer/alabanda-antik-tiyatrosu/", "quote": "Alabanda Antik Tiyatrosu Type Ancient Theater", "outcome": "found"}, {"source": "https://www.worldhistory.org/image/9936/the-hellenistic-theatre-of-alabanda/", "url": "https://www.worldhistory.org/image/9936/the-hellenistic-theatre-of-alabanda/", "quote": "The Hellenistic theatre of Alabanda, located on a natural south-facing hillside.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0140)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the city of Alabanda, not its theatre, and no Wikipedia article covers the theatre alone; the Kültür Envanteri heritage inventory entry for the Alabanda Antik Tiyatrosu is a plain-HTML page about this very theatre, and the World History Encyclopedia names the same theatre.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('2a4b62ce-c1d8-4def-ba57-ec8c77edb502'::uuid, 'period_name', '3000 - 1500 BC', '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s002-rollback:2a4b62ce-c1d8-4def-ba57-ec8c77edb502:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''4500 - 3000 BC'' restored on Nine Ladies Stone Circle', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-2000) = ''3000 - 1500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2a4b62ce-c1d8-4def-ba57-ec8c77edb502'::uuid, 'period_start', '-2000', '-4500', 'fields-wd1-2026-09-26b-s002-rollback:2a4b62ce-c1d8-4def-ba57-ec8c77edb502:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-4500'' restored on Nine Ladies Stone Circle', '[{"source": "http://www.stone-circles.org.uk/stone/nineladies.htm", "url": "http://www.stone-circles.org.uk/stone/nineladies.htm", "quote": "then the circle probably dates from the early Bronze Age, perhaps sometime between 2000-1500BC.", "outcome": "found"}, {"source": "https://her.derbyshire.gov.uk/monument/MDR3735", "url": "https://her.derbyshire.gov.uk/monument/MDR3735", "quote": "EMBANKED STONE CIRCLE (Bronze Age - 2350 BC to 701 BC)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0042)", "decision": "replace", "status": "MISSING", "reasoning": "The Derbyshire HER classes the Nine Ladies as a Bronze Age embanked stone circle (2350 BC to 701 BC) and stone-circles.org.uk dates it to the early Bronze Age, perhaps 2000-1500 BC; both put the start in 3000-1500 BC, not in the stored 4500-3000 BC bucket, so the value becomes c. 2000 BC.", "value_page": null}]'::jsonb),
    ('2acd40c5-e1dd-4ea1-9378-8c4e28acd415'::uuid, 'site_type', 'Amphitheatre', 'Megalithic structures', 'fields-wd1-2026-09-26b-s002-rollback:2acd40c5-e1dd-4ea1-9378-8c4e28acd415:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic structures'' restored on Roman Amphitheatre', '[{"source": "https://en.wikipedia.org/wiki/Carthage_amphitheatre", "url": "https://en.wikipedia.org/wiki/Carthage_amphitheatre", "quote": "The Carthage Amphitheatre was a Roman amphitheatre constructed in the first century CE in the city of Carthage, Tunisia", "outcome": "found"}, {"source": "https://www.worldhistory.org/image/21016/roman-amphitheatre-of-carthage/", "url": "https://www.worldhistory.org/image/21016/roman-amphitheatre-of-carthage/", "quote": "Ruins of the Roman amphitheatre in ancient Carthage, photograph by Carole Raddato, Tunisia, 12 February, 2023.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0140)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources describe the site as the Roman amphitheatre of Carthage, not a megalithic structure, so the specific canonical type is Amphitheatre.", "value_page": null}]'::jsonb),
    ('2ad48d55-42d5-4f11-a884-e87084048ead'::uuid, 'site_type', 'Sanctuary', 'Temple complex', 'fields-wd1-2026-09-26b-s002-rollback:2ad48d55-42d5-4f11-a884-e87084048ead:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Temple complex'' restored on Archaeological Site of Eleusis', '[{"source": "https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis", "url": "https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis", "quote": "Le sanctuaire d''Éleusis ou sanctuaire des Grandes Déesses est le lieu d''initiation des citoyens d''Athènes et d''autres cités grecques aux rites des mystères d''Éleusis", "outcome": "found"}, {"source": "https://topostext.org/place/380235SEle", "url": "https://topostext.org/place/380235SEle", "quote": "The sanctuary is entered today, as in antiquity, through a large paved court (2nd century AD) where three roads terminated", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "MISSING", "reasoning": "Both sources describe the archaeological site of Eleusis as the sanctuary of Demeter and Kore, a sacred precinct of the Mysteries around the Telesterion, with several temples inside it; Sanctuary is the type the sources name.", "value_page": null}]'::jsonb),
    ('2ad48d55-42d5-4f11-a884-e87084048ead'::uuid, 'source_url', 'https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis', 'https://ancient-greece.org/images/ancient-sites/elefsina/elefsina.html', 'fields-wd1-2026-09-26b-s002-rollback:2ad48d55-42d5-4f11-a884-e87084048ead:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://ancient-greece.org/images/ancient-sites/elefsina/elefsina.html'' restored on Archaeological Site of Eleusis', '[{"source": "https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis", "url": "https://fr.wikipedia.org/wiki/Sanctuaire_d%27%C3%89leusis", "quote": "Le sanctuaire d''Éleusis ou sanctuaire des Grandes Déesses est le lieu d''initiation des citoyens d''Athènes et d''autres cités grecques aux rites des mystères d''Éleusis", "outcome": "found"}, {"source": "https://topostext.org/place/380235SEle", "url": "https://topostext.org/place/380235SEle", "quote": "Eleusinian Demeter sanctuary (Attica)", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored ancient-greece.org page returns 404; English Wikipedia has no article on the sanctuary itself (Eleusis is the town), while the French Wikipedia article ''Sanctuaire d''Éleusis'' is about this archaeological site, which ToposText independently names.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Sanctuaire d''Éleusis", "unreadable": false, "wikibase_item": "Q94299853"}}]'::jsonb),
    ('2b060651-4865-490c-8eb1-993a80533c26'::uuid, 'site_type', 'City', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:2b060651-4865-490c-8eb1-993a80533c26:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Acrópolis Aguateca', '[{"source": "https://en.wikipedia.org/wiki/Aguateca", "url": "https://en.wikipedia.org/wiki/Aguateca", "quote": "Aguateca became a large, densely populated city, with a higher density of structures than most other lowland Maya sites.", "outcome": "found"}, {"source": "https://www.guatemala.com/guias/aventura/la-antigua-ciudad-maya-aguateca/", "url": "https://www.guatemala.com/guias/aventura/la-antigua-ciudad-maya-aguateca/", "quote": "La antigua ciudad maya Aguateca, ubicada en la región de Petexbatún, en Petén, es uno de los sitios arqueológicos más interesantes de Guatemala.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia describes Aguateca as a large, densely populated city, the second capital of the Petexbatún dynasty, and Guatemala.com calls it the ancient Maya city (antigua ciudad maya) of Aguateca, so the specific type City fits.", "value_page": null}]'::jsonb),
