    ('2b3667ad-f83a-4514-8ef9-62231a454215'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Poghjaredda', 'https://en.wikipedia.org/wiki/Pughjaredda', 'fields-wd1-2026-09-26b-s002-rollback:2b3667ad-f83a-4514-8ef9-62231a454215:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Pughjaredda'' restored on Pughjaredda', '[{"source": "https://en.wikipedia.org/wiki/Poghjaredda", "url": "https://en.wikipedia.org/wiki/Poghjaredda", "quote": "Poghjaredda (also known as Pughjaredda) is an archaeological site in Corsica. It is located in the commune of Sotta.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=6340958", "url": "https://www.megalithic.co.uk/article.php?sid=6340958", "quote": "Dolmen de Poghjaredda is a Dolmen in the community of Sotta, Departement of Corse du Sud, Region of Corse", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0054)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is a redirect to the English article ''Poghjaredda'', which is about this very site in Sotta (the Megalithic Portal names the same dolmen complex); the field is replaced by the article''s own URL.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Poghjaredda", "unreadable": false, "wikibase_item": "Q7258957"}}]'::jsonb),
    ('2bbc9730-d938-4fd5-a8e5-594ea046d183'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:2bbc9730-d938-4fd5-a8e5-594ea046d183:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Yarrows Broch', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2bbc9730-d938-4fd5-a8e5-594ea046d183'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s002-rollback:2bbc9730-d938-4fd5-a8e5-594ea046d183:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Yarrows Broch', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "clear", "status": "MISSING", "reasoning": "No source dates Yarrows Broch itself: the Highland HER gives only the band ''Early Iron Age to Medieval - 550 BC to 1559 AD'', Yarrows Heritage gives the generic broch range 200 BC - AD 200, and Dutch Wikipedia says the place was probably used from 500 BC but the broch is probably later; the start is not attested, so the field is emptied.", "value_page": null}]'::jsonb),
    ('2bbc9730-d938-4fd5-a8e5-594ea046d183'::uuid, 'site_type', 'Minaret/tower', 'Underwater structures', 'fields-wd1-2026-09-26b-s002-rollback:2bbc9730-d938-4fd5-a8e5-594ea046d183:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Underwater structures'' restored on Yarrows Broch', '[{"source": "https://her.highland.gov.uk/Monument/MHG1937", "url": "https://her.highland.gov.uk/Monument/MHG1937", "quote": "sunk at least 0.6m deep into the shoulder of the grass-grown mound of rubble that now surrounds the ruined tower.", "outcome": "found"}, {"source": "https://www.yarrowsheritage.co.uk/yarrows-broch", "url": "https://www.yarrowsheritage.co.uk/yarrows-broch", "quote": "They are complex, hollow-walled, windowless, stone towers found mainly in the North of Scotland", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "CONFLICT", "reasoning": "Yarrows is an Iron Age broch, a drystone tower on the shore of the Loch of Yarrows that floods only since the loch was dammed; the Highland HER calls it the ruined tower and Yarrows Heritage describes brochs as stone towers, so it is a tower, not an underwater structure.", "value_page": null}]'::jsonb),
    ('2bbc9730-d938-4fd5-a8e5-594ea046d183'::uuid, 'source_url', 'https://nl.wikipedia.org/wiki/Broch_of_Yarrows', 'https://en.wikipedia.org/wiki/Iron_Age', 'fields-wd1-2026-09-26b-s002-rollback:2bbc9730-d938-4fd5-a8e5-594ea046d183:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Iron_Age'' restored on Yarrows Broch', '[{"source": "https://nl.wikipedia.org/wiki/Broch_of_Yarrows", "url": "https://nl.wikipedia.org/wiki/Broch_of_Yarrows", "quote": "De Broch of Yarrows ligt op een kleine landtong aan de zuidwestelijke zijde van een klein meertje, dat Loch of Yarrows heet.", "outcome": "found"}, {"source": "https://www.yarrowsheritage.co.uk/yarrows-broch", "url": "https://www.yarrowsheritage.co.uk/yarrows-broch", "quote": "Yarrows broch is now submerged in water because the level of the loch has risen about a metre after the loch was dammed in the early 20th century.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0124)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL is the general Iron Age article; the broch has no English article, and the Dutch Wikipedia article ''Broch of Yarrows'' is the site''s own article, the same broch Yarrows Heritage describes.", "value_page": {"lang": "nl", "problem": null, "resolved_title": "Broch of Yarrows", "unreadable": false, "wikibase_item": "Q747937"}}]'::jsonb),
    ('2c1c70ac-91df-4577-ac77-3bedd6c521ee'::uuid, 'period_name', NULL, '1000 - 1500 AD', 'fields-wd1-2026-09-26b-s002-rollback:2c1c70ac-91df-4577-ac77-3bedd6c521ee:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1000 - 1500 AD'' restored on Auquilohuagra', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2c1c70ac-91df-4577-ac77-3bedd6c521ee'::uuid, 'period_start', NULL, '1400', 'fields-wd1-2026-09-26b-s002-rollback:2c1c70ac-91df-4577-ac77-3bedd6c521ee:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1400'' restored on Auquilohuagra', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call the constructions only ''de época pre inca'' and link the inhabitants to the Yarowilca nation; no source gives a year, century or millennium for the site''s start, so the stored 1400 cannot be supported and the field is emptied.", "value_page": null}]'::jsonb),
    ('2c1c70ac-91df-4577-ac77-3bedd6c521ee'::uuid, 'site_type', NULL, 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:2c1c70ac-91df-4577-ac77-3bedd6c521ee:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Auquilohuagra', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "clear", "status": "MISSING", "reasoning": "Spanish Wikipedia types the site ''Asentamiento'' and the MINCETUR inventory entry (turismoperuano.com) describes corrals, passageways, small dwellings and a collca, which fits the stored settlement type, but no page found states a type word in English (English Wikipedia and its mirrors say only ''archaeological site''), so the type cannot be quoted as required and the field is emptied for the owner to review.", "value_page": null}]'::jsonb),
    ('2c2eaf7a-0c07-460c-8893-9a0443f8f9d4'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s002-rollback:2c2eaf7a-0c07-460c-8893-9a0443f8f9d4:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''4500 - 3000 BC'' restored on Ljuljaci', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2c2eaf7a-0c07-460c-8893-9a0443f8f9d4'::uuid, 'period_start', NULL, '-4000', 'fields-wd1-2026-09-26b-s002-rollback:2c2eaf7a-0c07-460c-8893-9a0443f8f9d4:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-4000'' restored on Ljuljaci', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "clear", "status": "MISSING", "reasoning": "Sources disagree on the date of the Ljuljaci tumuli: English Wikipedia says Bronze Age, Serbian Wikipedia Early Iron Age, and Balcanica dates the two excavated mounds to the 5th-3rd centuries BC; no two independent readable sources date the start, and the stored -4000 is supported by none.", "value_page": null}]'::jsonb),
    ('2c2eaf7a-0c07-460c-8893-9a0443f8f9d4'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Ljuljaci', 'fields-wd1-2026-09-26b-s002-rollback:2c2eaf7a-0c07-460c-8893-9a0443f8f9d4:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Ljuljaci'' restored on Ljuljaci', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the village of Ljuljaci, not the tumulus necropolis; no web page about the necropolis itself (only bibliographic records and passing mentions) could be found.", "value_page": null}]'::jsonb),
    ('2c36db5a-566a-4bda-ad03-f14936f83eb8'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd1-2026-09-26b-s002-rollback:2c36db5a-566a-4bda-ad03-f14936f83eb8:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''4500 - 3000 BC'' restored on Deer Valley Petroglyph Preserve', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2c36db5a-566a-4bda-ad03-f14936f83eb8'::uuid, 'period_start', NULL, '-4500', 'fields-wd1-2026-09-26b-s002-rollback:2c36db5a-566a-4bda-ad03-f14936f83eb8:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-4500'' restored on Deer Valley Petroglyph Preserve', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0149)", "decision": "clear", "status": "MISSING", "reasoning": "The sources give the age of the petroglyphs only as ''500 to 5,000 years old'' (not read) and give the spans of the Western Archaic tradition in general (about 5000 BC per Wikipedia, 8000-3000 BCE per ASU), not a start date for this site; no two sources date the site''s start.", "value_page": null}]'::jsonb),
    ('2cd65076-e10c-401f-a997-296f99badf9c'::uuid, 'period_name', NULL, '1500 - 500 BC', 'fields-wd1-2026-09-26b-s002-rollback:2cd65076-e10c-401f-a997-296f99badf9c:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1500 - 500 BC'' restored on Bredon Hill', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2cd65076-e10c-401f-a997-296f99badf9c'::uuid, 'period_start', NULL, '-1500', 'fields-wd1-2026-09-26b-s002-rollback:2cd65076-e10c-401f-a997-296f99badf9c:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1500'' restored on Bredon Hill', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "clear", "status": "MISSING", "reasoning": "Only the Megalithic Portal gives a year (''The inner ramparts possibly date to 300BC'', hedged), and Wikipedia''s Kemerton article repeats it citing that very page; other sources say only ''Begun in the early iron age''. No two independent sources date the start, and nothing supports the stored -1500.", "value_page": null}]'::jsonb),
    ('2cd65076-e10c-401f-a997-296f99badf9c'::uuid, 'site_type', 'Fort', 'Earthwork', 'fields-wd1-2026-09-26b-s002-rollback:2cd65076-e10c-401f-a997-296f99badf9c:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Earthwork'' restored on Bredon Hill', '[{"source": "https://www.megalithic.co.uk/article.php?sid=5111", "url": "https://www.megalithic.co.uk/article.php?sid=5111", "quote": "Kemerton Camp is a promontory fort with a steep escarpment dropping away on the north side of the Hill, it has two sets of ramparts and ditches to the south.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Bredon_Hill", "url": "https://en.wikipedia.org/wiki/Bredon_Hill", "quote": "At the summit of the hill, there are the remains of earthworks from an Iron Age hill fort known as Kemerton Camp", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "Both sources say the earthworks on the summit of Bredon Hill are an Iron Age hillfort, Kemerton Camp; Fort is more specific than the generic Earthwork.", "value_page": null}]'::jsonb),
    ('2cd65076-e10c-401f-a997-296f99badf9c'::uuid, 'source_url', 'https://www.megalithic.co.uk/article.php?sid=5111', 'https://en.wikipedia.org/wiki/Bredon_Hill', 'fields-wd1-2026-09-26b-s002-rollback:2cd65076-e10c-401f-a997-296f99badf9c:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Bredon_Hill'' restored on Bredon Hill', '[{"source": "https://www.megalithic.co.uk/article.php?sid=5111", "url": "https://www.megalithic.co.uk/article.php?sid=5111", "quote": "Kemerton Camp is a hillfort on the top of Bredon Hill in Worcestershire.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Bredon_Hill", "url": "https://en.wikipedia.org/wiki/Bredon_Hill", "quote": "At the summit of the hill, there are the remains of earthworks from an Iron Age hill fort known as Kemerton Camp", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0028)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Wikipedia article is about the hill, and Kemerton Camp has no Wikipedia article; the Megalithic Portal''s Kemerton Camp page is about the hillfort itself and loads as plain HTML (the Historic England list entry 1005331 cannot be read by the checker).", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
