    ('2d89e6d4-8fa0-4258-a70a-bc42ad3c47bf'::uuid, 'period_name', '1000 - 1500 AD', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:2d89e6d4-8fa0-4258-a70a-bc42ad3c47bf:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Neuchâtel', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(1011) = ''1000 - 1500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2d89e6d4-8fa0-4258-a70a-bc42ad3c47bf'::uuid, 'period_start', '1011', '-500', 'fields-wd1-2026-09-26b-s002-rollback:2d89e6d4-8fa0-4258-a70a-bc42ad3c47bf:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Neuchâtel', '[{"source": "https://en.wikipedia.org/wiki/Neuch%C3%A2tel", "url": "https://en.wikipedia.org/wiki/Neuch%C3%A2tel", "quote": "In 1011, Rudolph III of Burgundy presented a Novum castellum or new castle on the lake shore to his wife", "outcome": "found"}, {"source": "https://hls-dhs-dss.ch/fr/articles/002853/", "url": "https://hls-dhs-dss.ch/fr/articles/002853/", "quote": "à sa fiancée Irmengarde, le 24 avril 1011.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0138)", "decision": "replace", "status": "CONFLICT", "reasoning": "The town''s history begins with the royal castle (Novum castellum) first recorded in Rudolph III''s donation of 1011, as Wikipedia and the Historical Dictionary of Switzerland both state (the HLS dates the first fortification of the spur to the end of the 10th century, just before it). The HLS notes that no Bronze or Iron Age settlement on the castle hill is verified, so the stored -500 has no support; the Neolithic lake village and Magdalenian camp in the municipal area are separate earlier sites.", "value_page": null}]'::jsonb),
