    ('2dcdec07-a26e-42bc-9490-b277628835f5'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Myeonghwalseong', 'https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas', 'fields-wd1-2026-09-26b-s002-rollback:2dcdec07-a26e-42bc-9490-b277628835f5:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Gyeongju_Historic_Areas'' restored on The Sanseong Belt', '[{"source": "https://en.wikipedia.org/wiki/Myeonghwalseong", "url": "https://en.wikipedia.org/wiki/Myeonghwalseong", "quote": "as part of the Sanseong Fortress Belt.", "outcome": "found"}, {"source": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0000470000000&sCcebCtcd=37", "url": "https://english.khs.go.kr/chaen/search/selectGeneralSearchDetail.do?mn=EN_02_02&sCcebKdcd=13&ccebAsno=0000470000000&sCcebCtcd=37", "quote": "The inscription on the Monument of Construction of Myeonghwalsanseong described the situation during the reign of King Jinheung, and pieces of the monument of Myeonghwalsanseong were discovered.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0128)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on the whole World Heritage property (Q495241). The English Wikipedia article on Myeonghwalseong states that the fortress forms the Sanseong Fortress Belt of the property, so it is the page about this site; the Korea Heritage Service register describes the same fortress.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Myeonghwalseong", "unreadable": false, "wikibase_item": "Q16092219"}}]'::jsonb),
    ('2e117929-e3f1-48d5-8abe-cf58ffb9e9e7'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:2e117929-e3f1-48d5-8abe-cf58ffb9e9e7:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Chisbury', '[{"source": "https://www.british-history.ac.uk/vch/wilts/vol16/pp50-69", "url": "https://www.british-history.ac.uk/vch/wilts/vol16/pp50-69", "quote": "At 176 m. Chisbury hill fort is the highest point in the parish", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=24243", "url": "https://www.megalithic.co.uk/article.php?sid=24243", "quote": "Site Name: Chisbury Camp Country: England County: Wiltshire Type: Hillfort", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0031)", "decision": "replace", "status": "CONFLICT", "reasoning": "The Victoria County History and the Megalithic Portal describe the site as an Iron Age hill fort (Chisbury Camp); Fort is the specific canonical type for a hillfort, rather than Fortress/citadel.", "value_page": null}]'::jsonb),
    ('2e23ad32-b50b-4439-8260-fe854b891c5d'::uuid, 'site_type', 'Tomb', 'Necropolis/tombs complex', 'fields-wd1-2026-09-26b-s002-rollback:2e23ad32-b50b-4439-8260-fe854b891c5d:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Necropolis/tombs complex'' restored on Massinissa Mausoleum', '[{"source": "https://journals.openedition.org/anneemaghreb/4025", "url": "https://journals.openedition.org/anneemaghreb/4025", "quote": "Near Constantine (Algeria) lies a Numidian tomb. It is usually called Soumaâ du Khroub (“Tower of El Khroub”) or “Tomb of Massinissa”, alluding to a famous king of Numidia (202-148 aC).", "outcome": "found"}, {"source": "https://fr.wikipedia.org/wiki/Souma%C3%A2_du_Khroub", "url": "https://fr.wikipedia.org/wiki/Souma%C3%A2_du_Khroub", "quote": "La Soumaâ du Khroub ou Mausolée royal numide d''El Khroub, surnommé Tombeau de Massinissa en référence au roi numide Massinissa, est un monument funéraire d''époque numide, situé à El Khroub dans la wilaya de Constantine, non loin de l''antique Cirta, capitale du royaume de Numidie.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cazeaux (L''Année du Maghreb) and French Wikipedia describe the site as a single Numidian royal tomb (a tower mausoleum), not a necropolis; the most specific type is Tomb.", "value_page": null}]'::jsonb),
    ('2e23ad32-b50b-4439-8260-fe854b891c5d'::uuid, 'source_url', 'https://fr.wikipedia.org/wiki/Souma%C3%A2_du_Khroub', 'https://en.wikipedia.org/wiki/Masinissa', 'fields-wd1-2026-09-26b-s002-rollback:2e23ad32-b50b-4439-8260-fe854b891c5d:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Masinissa'' restored on Massinissa Mausoleum', '[{"source": "https://fr.wikipedia.org/wiki/Souma%C3%A2_du_Khroub", "url": "https://fr.wikipedia.org/wiki/Souma%C3%A2_du_Khroub", "quote": "La Soumaâ du Khroub ou Mausolée royal numide d''El Khroub, surnommé Tombeau de Massinissa en référence au roi numide Massinissa, est un monument funéraire d''époque numide, situé à El Khroub dans la wilaya de Constantine, non loin de l''antique Cirta, capitale du royaume de Numidie.", "outcome": "found"}, {"source": "https://journals.openedition.org/anneemaghreb/4025", "url": "https://journals.openedition.org/anneemaghreb/4025", "quote": "Near Constantine (Algeria) lies a Numidian tomb. It is usually called Soumaâ du Khroub (“Tower of El Khroub”) or “Tomb of Massinissa”, alluding to a famous king of Numidia (202-148 aC).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0003)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article is the biography of King Masinissa; the monument has no English article, and French Wikipedia''s Soumaâ du Khroub is the article about this mausoleum, confirmed by Cazeaux''s study of the same ''Tomb of Massinissa''.", "value_page": {"lang": "fr", "problem": null, "resolved_title": "Soumaâ du Khroub", "unreadable": false, "wikibase_item": "Q85829801"}}]'::jsonb),
    ('2e8550b6-1358-471f-9be5-9957b2613c9d'::uuid, 'site_type', 'Fort', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:2e8550b6-1358-471f-9be5-9957b2613c9d:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Mynydd Maendy', '[{"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2866", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2866", "quote": "The hillfort is situated on a hilltop on the west side of the Rhondda valley.", "outcome": "found"}, {"source": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT00053m", "url": "https://archwilio.org.uk/her/chi3/report/page.php?watprn=GGAT00053m", "quote": "An iron age hill fort situated on the edge of an ENE facing ridge over-looking the Rhondda Valley.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "Cadw (site type Hillfort) and the Glamorgan-Gwent HER record for Maendy Camp (site type Iron Age - Hillfort, ''Iron age hill fort'') both describe a hillfort; nothing calls it a fortress or citadel, and the hill class of the item is not the site''s type, so the specific canonical type is Fort.", "value_page": null}]'::jsonb),
    ('2e8550b6-1358-471f-9be5-9957b2613c9d'::uuid, 'source_url', 'https://coflein.gov.uk/en/sites/301331', 'https://en.wikipedia.org/wiki/Mynydd_Maendy', 'fields-wd1-2026-09-26b-s002-rollback:2e8550b6-1358-471f-9be5-9957b2613c9d:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Mynydd_Maendy'' restored on Mynydd Maendy', '[{"source": "https://coflein.gov.uk/en/sites/301331", "url": "https://coflein.gov.uk/en/sites/301331", "quote": "Set on the ridge of Mynydd Maendy, is a sub-oval enclosure, c.110m N-S by 98m, defined by a rubble bank with an external ditch.", "outcome": "found"}, {"source": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2866", "url": "https://cadwpublic-api.azurewebsites.net/reports/sam/FullReport?id=2866", "quote": "The hillfort is situated on a hilltop on the west side of the Rhondda valley.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0155)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article describes the hilltop and moorland near Gilfach Goch and mislocates the hillfort on its summit; the RCAHMW Coflein record NPRN 301331 (Maindy Camp; Maendy Camp, a hillfort on the ridge of Mynydd Maendy) is about the hillfort itself, and Cadw''s record for Mynydd Maendy Hillfort describes the same monument independently.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
