    ('2ed572b3-bf48-4f8d-a638-387b6484c962'::uuid, 'site_type', 'Monastery', 'Temple complex', 'fields-wd1-2026-09-26b-s002-rollback:2ed572b3-bf48-4f8d-a638-387b6484c962:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Temple complex'' restored on Shaji-ki-Dheri', '[{"source": "https://doam.gov.pk/public/sites/1809", "url": "https://doam.gov.pk/public/sites/1809", "quote": "Type: Archaeological Site - Stupa & Monastery", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Kanishka_Stupa", "url": "https://en.wikipedia.org/wiki/Kanishka_Stupa", "quote": "The monastery and the stupa were built by the former king Kanishka", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0105)", "decision": "replace", "status": "MISSING", "reasoning": "The national register types the site as a stupa and monastery, and the pilgrim account quoted by Wikipedia names the Kanishka monastery with its stupa; it is a Buddhist stupa-monastery complex, not a temple complex, so Monastery is the closest canonical type.", "value_page": null}]'::jsonb),
    ('2f70b365-8c72-45e5-9750-051428089daa'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd1-2026-09-26b-s002-rollback:2f70b365-8c72-45e5-9750-051428089daa:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''1 - 500 AD'' restored on Costa Beck', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('2f70b365-8c72-45e5-9750-051428089daa'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s002-rollback:2f70b365-8c72-45e5-9750-051428089daa:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Costa Beck', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "clear", "status": "MISSING", "reasoning": "The sources call the settlement Iron Age and Romano-British; the excavation report itself only ''would like to postulate'' occupation between 100 BC and AD 100 and says it ''cannot be proved''. No two sources date the start of the site, so the field is emptied.", "value_page": null}]'::jsonb),
    ('2f70b365-8c72-45e5-9750-051428089daa'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:2f70b365-8c72-45e5-9750-051428089daa:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Costa Beck', '[{"source": "https://en.wikipedia.org/wiki/Costa_Beck", "url": "https://en.wikipedia.org/wiki/Costa_Beck", "quote": "The excavations showed the presence of an Iron Age and Romano-British lakeside settlement.", "outcome": "found"}, {"source": "https://www.yorkpress.co.uk/features/features/9322202.fishy-tale-of-pickerings-origins/", "url": "https://www.yorkpress.co.uk/features/features/9322202.fishy-tale-of-pickerings-origins/", "quote": "there is evidence of Neolithic barrows and dykes in the Vale of Pickering, and of an Iron Age settlement on the banks of Costa Beck", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "replace", "status": "CONFLICT", "reasoning": "Wikipedia and The York Press both describe the Costa Beck site as an Iron Age (and Romano-British) settlement - a lakeside pile-dwelling, not a city or town - so the specific canonical type Settlement replaces ''City/town/settlement''.", "value_page": null}]'::jsonb),
    ('2f70b365-8c72-45e5-9750-051428089daa'::uuid, 'source_url', NULL, 'https://en.wikipedia.org/wiki/Costa_Beck', 'fields-wd1-2026-09-26b-s002-rollback:2f70b365-8c72-45e5-9750-051428089daa:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Costa_Beck'' restored on Costa Beck', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0032)", "decision": "clear", "status": "CONFLICT", "reasoning": "The stored article is about the river Costa Beck, which only ''lends its name to an archaeological site'' in a short section. The site has no article of its own; the Historic England research record (60325) about it refuses automated requests and the 1931 excavation report exists only as a scanned journal volume, so no readable page about this very site can be named.", "value_page": null}]'::jsonb),
