    ('30d3fb78-6b80-42f9-87f8-7616e63bec4f'::uuid, 'period_start', '-1000', '1', 'fields-wd1-2026-09-26b-s002-rollback:30d3fb78-6b80-42f9-87f8-7616e63bec4f:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Tikal', '[{"source": "https://en.wikipedia.org/wiki/Tikal", "url": "https://en.wikipedia.org/wiki/Tikal", "quote": "There are traces of early agriculture at the site dating as far back as 1000 BC, in the Middle Preclassic.", "outcome": "found"}, {"source": "https://uncoveredhistory.com/guatemala/tikal/tikal-a-brief-history/", "url": "https://uncoveredhistory.com/guatemala/tikal/tikal-a-brief-history/", "quote": "The first signs of occupation at Tikal date as far back as 1000BC in a period known as the Middle Preclassic.", "outcome": "found"}, {"source": "https://tikalnationalpark.org/", "url": "https://tikalnationalpark.org/", "quote": "Archaeologists estimate that the Maya settled in the area now known as Tikal in about 900 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0076)", "decision": "replace", "status": "MISSING", "reasoning": "English Wikipedia and Uncovered History date the first occupation of Tikal to c. 1000 BC in the Middle Preclassic (the Tikal National Park page gives about 900 BC, likewise in the 1500 - 500 BC bucket); the stored start of AD 1 misses the whole Preclassic history, so it is replaced by -1000.", "value_page": null}]'::jsonb),
    ('30d3fb78-6b80-42f9-87f8-7616e63bec4f'::uuid, 'site_type', 'City/town/settlement, Pyramid complex', 'Pyramid complex', 'fields-wd1-2026-09-26b-s002-rollback:30d3fb78-6b80-42f9-87f8-7616e63bec4f:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Pyramid complex'' restored on Tikal', '[{"source": "https://en.wikipedia.org/wiki/Tikal", "url": "https://en.wikipedia.org/wiki/Tikal", "quote": "is the ruin of an ancient city, which was likely to have been called Yax Mutal", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Tikal", "url": "https://en.wikipedia.org/wiki/Tikal", "quote": "There are nine Twin-pyramid complexes at Tikal, one of which was completely dismantled in ancient times and some others were partly destroyed.", "outcome": "found"}, {"source": "https://tikalnationalpark.org/", "url": "https://tikalnationalpark.org/", "quote": "Most of the city’s massive temples were constructed during the eighth century AD when Tikal became the most fantastic city in the Maya world, with a population of perhaps 100,000.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0076)", "decision": "replace", "status": "MISSING", "reasoning": "The sources describe Tikal first as an ancient Maya city of some 3,000 buildings and up to 100,000 people, whose temple-pyramids and nine twin-pyramid complexes define it; the combined canonical type City/town/settlement, Pyramid complex holds both, whereas Pyramid complex alone names only part of the city.", "value_page": null}]'::jsonb),
    ('30d3fb78-6b80-42f9-87f8-7616e63bec4f'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Tikal', 'https://en.wikipedia.org/wiki/Mundo_Perdido,_Tikal', 'fields-wd1-2026-09-26b-s002-rollback:30d3fb78-6b80-42f9-87f8-7616e63bec4f:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Mundo_Perdido,_Tikal'' restored on Tikal', '[{"source": "https://en.wikipedia.org/wiki/Tikal", "url": "https://en.wikipedia.org/wiki/Tikal", "quote": "There are nine Twin-pyramid complexes at Tikal, one of which was completely dismantled in ancient times and some others were partly destroyed.", "outcome": "found"}, {"source": "https://tikalnationalpark.org/", "url": "https://tikalnationalpark.org/", "quote": "Archaeologists estimate that the Maya settled in the area now known as Tikal in about 900 BC.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0076)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored page is the article on Mundo Perdido, one complex within Tikal; the site''s own English Wikipedia article is https://en.wikipedia.org/wiki/Tikal, which covers the whole city.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Tikal", "unreadable": false, "wikibase_item": "Q181172"}}]'::jsonb),
