    ('30dba5dd-d925-4fbf-a84c-ed9c20f1f286'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Knossos', 'https://en.wikipedia.org/wiki/Kephala', 'fields-wd1-2026-09-26b-s002-rollback:30dba5dd-d925-4fbf-a84c-ed9c20f1f286:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Kephala'' restored on Kephala', '[{"source": "https://en.wikipedia.org/wiki/Knossos", "url": "https://en.wikipedia.org/wiki/Knossos", "quote": "Knossos lies on Kephala hill, in the valley of the Kairatos river, within the modern municipality of Heraklion, about 5 km (3.1 mi) south of the historic centre.", "outcome": "found"}, {"source": "https://www.heraklion.gr/en/ourplace/knossos/knossos.html", "url": "https://www.heraklion.gr/en/ourplace/knossos/knossos.html", "quote": "The palace was built on the Kephala hill and had easy access to the sea and the Cretan interior.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0066)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored article describes the hill as a landform; the settlement on Kephala hill is the archaeological site of Knossos, whose English Wikipedia article covers it from the Neolithic onward.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Knossos", "unreadable": false, "wikibase_item": "Q173527"}}]'::jsonb),
