    ('317314f2-db25-4249-a5b7-f388a2042839'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Norba', 'https://comune.norma.lt.it/contenuti/38972/antica-norba', 'fields-wd1-2026-09-26b-s002-rollback:317314f2-db25-4249-a5b7-f388a2042839:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://comune.norma.lt.it/contenuti/38972/antica-norba'' restored on Parco Archeologico Antica Norba', '[{"source": "https://en.wikipedia.org/wiki/Norba", "url": "https://en.wikipedia.org/wiki/Norba", "quote": "Norba, an ancient town of Latium (Adjectum), Italy. It is situated 1 mile northwest of the modern town of Norma", "outcome": "found"}, {"source": "https://comune.norma.lt.it/luoghi/2561916/parco-archeologico-antica-citta-norba", "url": "https://comune.norma.lt.it/luoghi/2561916/parco-archeologico-antica-citta-norba", "quote": "L''Antica Città di Norba sorge a poca distanza dalla moderna Norma.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored Comune di Norma URL returns 404; English Wikipedia''s Norba article is about this ancient town near Norma, whose archaeological park the Comune di Norma''s current page describes.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Norba", "unreadable": false, "wikibase_item": "Q2026618"}}]'::jsonb),
