    ('317436c1-4827-4db2-acf6-1238452a5e86'::uuid, 'period_start', NULL, '1', 'fields-wd1-2026-09-26b-s002-rollback:317436c1-4827-4db2-acf6-1238452a5e86:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''1'' restored on Remesiana', '[{"source": "WD1 decision (counted, round 1, wd1-r1-b0023)", "decision": "clear", "status": "MISSING", "reasoning": "Sources disagree on when Remesiana began: Serbian municipal pages repeat Jirecek''s foundation by Celts around 280 BC, one heritage-tourism page says probably under Augustus (AD 12-14), while the national monument register and Serbian Wikipedia say only that the settlement formed early and probably got city status under Trajan; no two independent sources give the same year, century or millennium, so no start date is secure and the field is cleared.", "value_page": null}]'::jsonb),
