    ('3184361d-9f91-4237-bc93-77c9f752d306'::uuid, 'period_start', '-330', '-1000', 'fields-wd1-2026-09-26b-s002-rollback:3184361d-9f91-4237-bc93-77c9f752d306:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-1000'' restored on Daidala', '[{"source": "https://imperium.ahlfeldt.se/places/22669.html", "url": "https://imperium.ahlfeldt.se/places/22669.html", "quote": "temporal coverage: start date -330 end date 300", "outcome": "found"}, {"source": "https://topostext.org/place/368290UDai", "url": "https://topostext.org/place/368290UDai", "quote": "Livy (37.22), relating its liberation from siege by Antiochos III in 190 B.C., calls it a fortress of the Peraea.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0143)", "decision": "replace", "status": "MISSING", "reasoning": "DARE dates Daidala from -330 (Hellenistic), and ToposText (Princeton Encyclopedia, G. E. Bean) calls it a Hellenistic to Roman settlement first attested as a besieged fortress in 190 B.C.; both put the start in 500 BC - 1 AD, not in the stored 1500 - 500 BC bucket.", "value_page": null}]'::jsonb),
    ('31860bc4-476a-49bc-9f97-e25220063d19'::uuid, 'geom', 'SRID=4326;POINT(42.606167 42.388111)', '0101000020E6100000384AF9CCEC4C45408707774F4A304540', 'fields-wd1-2026-09-26b-s002-rollback:31860bc4-476a-49bc-9f97-e25220063d19:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E6100000384AF9CCEC4C45408707774F4A304540'' restored on Satsurblia Cave', '[{"source": "https://en.wikipedia.org/wiki/Satsurblia_Cave", "url": "https://en.wikipedia.org/wiki/Satsurblia_Cave", "quote": "42.388111°N 42.606167°E", "outcome": "found"}, {"source": "https://www.showcaves.com/english/ge/caves/Satsurblia.html", "url": "https://www.showcaves.com/english/ge/caves/Satsurblia.html", "quote": "42.387795, 42.606163", "outcome": "found"}, {"source": "https://travelguide.ge/en/what-to-do/satsurblias-mghvime/", "url": "https://travelguide.ge/en/what-to-do/satsurblias-mghvime/", "quote": "Location 42.3886, 42.6060", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "replace", "status": "CONFLICT", "reasoning": "English Wikipedia, Showcaves.com and TravelGuide.ge all put the cave entrance near Kumistavi at about 42.388, 42.606, within 0.1 km of one another (the National Parks of Georgia page gives N42 23.283 E42 36.376, the same spot). The stored point is 1.3 km to the south-south-west, so it is replaced.", "value_page": null}]'::jsonb),
