    ('31860bc4-476a-49bc-9f97-e25220063d19'::uuid, 'period_name', NULL, '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:31860bc4-476a-49bc-9f97-e25220063d19:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Satsurblia Cave', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(None) = None"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('31860bc4-476a-49bc-9f97-e25220063d19'::uuid, 'period_start', NULL, '-500', 'fields-wd1-2026-09-26b-s002-rollback:31860bc4-476a-49bc-9f97-e25220063d19:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Satsurblia Cave', '[{"source": "WD1 decision (counted, round 0, wd1-r0-b0056)", "decision": "clear", "status": "MISSING", "reasoning": "The first occupation is Upper Palaeolithic, dated in the literature only in radiocarbon years BP (about 25,500-24,400 BP per English Wikipedia and Pinhasi et al. 2014), which is not read. The only BC figures (Archiqoo''s ''around 23000 BC'', German Wikipedia''s ''25.500 v. Chr.'') are copies or conversions of the Wikipedia text, so no two independent sources state a BC start; the stored 500 BC is certainly wrong, so the field is emptied.", "value_page": null}]'::jsonb),
    ('31ba0428-1f43-411a-8473-0f1ade121091'::uuid, 'site_type', 'Settlement', 'City/town/settlement', 'fields-wd1-2026-09-26b-s002-rollback:31ba0428-1f43-411a-8473-0f1ade121091:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''City/town/settlement'' restored on Independence Fjord', '[{"source": "https://en.wikipedia.org/wiki/Independence_Fjord", "url": "https://en.wikipedia.org/wiki/Independence_Fjord", "quote": "The traces of ancient human settlements in the area have been the subject of research since the beginning of the 20th century.", "outcome": "found"}, {"source": "https://natmus.dk/organisation/forskning-og-kulturarv/nyere-tid-og-verdens-kulturer/etnografisk-samling/arktisk-forskning/prehistory-of-greenland/independence-i/", "url": "https://natmus.dk/organisation/forskning-og-kulturarv/nyere-tid-og-verdens-kulturer/etnografisk-samling/arktisk-forskning/prehistory-of-greenland/independence-i/", "quote": "Often we find five or more dwellings at a site indicating a basic working group of 20-30 people.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0074)", "decision": "replace", "status": "CONFLICT", "reasoning": "The remains around Independence Fjord are Palaeo-Eskimo dwelling sites (tent rings and mid-passage dwellings) of small groups; Wikipedia calls them ancient human settlements and the National Museum of Denmark describes groups of dwellings, so Settlement fits, not a city or town.", "value_page": null}]'::jsonb),
    ('31c676cd-4f5c-4e40-9bed-9c998f69eb81'::uuid, 'geom', 'SRID=4326;POINT(18.425733 40.007022)', '0101000020E610000034C0579E6A663240B16E6C9828024440', 'fields-wd1-2026-09-26b-s002-rollback:31c676cd-4f5c-4e40-9bed-9c998f69eb81:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E610000034C0579E6A663240B16E6C9828024440'' restored on Castro, Apulia', '[{"source": "https://it.wikipedia.org/wiki/Castro_(Puglia)", "url": "https://it.wikipedia.org/wiki/Castro_(Puglia)", "quote": "40°00′25.28″N 18°25′32.64″E", "outcome": "found"}, {"source": "https://topostext.org/place/400184UCMi", "url": "https://topostext.org/place/400184UCMi", "quote": "Latitude: 40.004300 Longitude: 18.428200", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/23193", "url": "https://imperium.ahlfeldt.se/places/23193", "quote": "40.00471, 18.42773", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "replace", "status": "CONFLICT", "reasoning": "Ancient Castrum Minervae lies under the old town of Castro on its coastal promontory: Italian Wikipedia, ToposText and the Digital Atlas of the Roman Empire place it within 400 m of each other at about 40.005-40.007, 18.426-18.428, while the stored point (a rounded 40°1''N 18°24''E from English Wikipedia) lies 2.4 km inland, so it is replaced.", "value_page": null}]'::jsonb),
