    ('31c676cd-4f5c-4e40-9bed-9c998f69eb81'::uuid, 'lon', '18.425733', '18.400064369605573', 'fields-wd1-2026-09-26b-s002-rollback:31c676cd-4f5c-4e40-9bed-9c998f69eb81:lon', 'rollback of fields-wd1-2026-09-26b-s002: lon ''18.400064369605573'' restored on Castro, Apulia', '[{"source": "https://it.wikipedia.org/wiki/Castro_(Puglia)", "url": "https://it.wikipedia.org/wiki/Castro_(Puglia)", "quote": "40°00′25.28″N 18°25′32.64″E", "outcome": "found"}, {"source": "https://topostext.org/place/400184UCMi", "url": "https://topostext.org/place/400184UCMi", "quote": "Latitude: 40.004300 Longitude: 18.428200", "outcome": "found"}, {"source": "https://imperium.ahlfeldt.se/places/23193", "url": "https://imperium.ahlfeldt.se/places/23193", "quote": "40.00471, 18.42773", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "replace", "status": "CONFLICT", "reasoning": "Ancient Castrum Minervae lies under the old town of Castro on its coastal promontory: Italian Wikipedia, ToposText and the Digital Atlas of the Roman Empire place it within 400 m of each other at about 40.005-40.007, 18.426-18.428, while the stored point (a rounded 40°1''N 18°24''E from English Wikipedia) lies 2.4 km inland, so it is replaced.", "value_page": null}]'::jsonb),
    ('31c676cd-4f5c-4e40-9bed-9c998f69eb81'::uuid, 'period_name', '1500 - 500 BC', '500 BC - 1 AD', 'fields-wd1-2026-09-26b-s002-rollback:31c676cd-4f5c-4e40-9bed-9c998f69eb81:period_name', 'rollback of fields-wd1-2026-09-26b-s002: period_name ''500 BC - 1 AD'' restored on Castro, Apulia', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-800) = ''1500 - 500 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}]'::jsonb),
    ('31c676cd-4f5c-4e40-9bed-9c998f69eb81'::uuid, 'period_start', '-800', '-500', 'fields-wd1-2026-09-26b-s002-rollback:31c676cd-4f5c-4e40-9bed-9c998f69eb81:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Castro, Apulia', '[{"source": "https://www.aeneasroute.org/en/tour/castro/", "url": "https://www.aeneasroute.org/en/tour/castro/", "quote": "Here the evidence of the oldest Iapigio settlement on the fortress have come to light, dating back to the Iron Age (VIII century B.C.) when there is already a place of worship.", "outcome": "found"}, {"source": "https://relicsquest.blogspot.com/2010/04/lathenaion-di-castro-fu-il-salento.html", "url": "https://relicsquest.blogspot.com/2010/04/lathenaion-di-castro-fu-il-salento.html", "quote": "popolata dai Messapi per testimonianze che risalgono all’VIII secolo a.C., la fortezza di Castro divenne colonia romana", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0084)", "decision": "replace", "status": "MISSING", "reasoning": "The University of Salento excavations found the oldest Iapygian settlement and cult place on the Castro promontory in the Iron Age, 8th century BC (Aeneas Route summary of D''Andria''s work; A Quest for Relics: Messapian occupation attested from the 8th century BC; also MEFRA: a context of the end of the 8th to early 7th century BC); this is earlier than the stored 500 BC bucket, so the start becomes -800 (the Bronze Age Palombara settlement is a separate locality at the foot of the town).", "value_page": null}]'::jsonb),
    ('31ee7df0-cf14-4c97-8d88-697625e5b913'::uuid, 'site_type', 'Temple complex', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:31ee7df0-cf14-4c97-8d88-697625e5b913:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Chanquillo', '[{"source": "https://news.bbc.co.uk/2/hi/science/nature/6408231.stm", "url": "https://news.bbc.co.uk/2/hi/science/nature/6408231.stm", "quote": "is believed to be a ceremonial centre that was occupied in the 4th Century BC. It is based at the coast of Peru in the Casma-Sechin River Basin and contains many buildings and plazas, as well as a fortified temple that has attracted much attention.", "outcome": "found"}, {"source": "https://www.theguardian.com/world/2021/jul/28/chankillo-oldest-solar-observatory-in-the-americas-awarded-unesco-world-heritage-status", "url": "https://www.theguardian.com/world/2021/jul/28/chankillo-oldest-solar-observatory-in-the-americas-awarded-unesco-world-heritage-status", "quote": "The site also includes an imposing triple-walled hilltop complex, known as the Fortified Temple set in the barren landscape of the Casma river valley.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Chanquillo", "url": "https://en.wikipedia.org/wiki/Chanquillo", "quote": "has been interpreted as a fortified temple", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0106)", "decision": "replace", "status": "CONFLICT", "reasoning": "Chankillo is a ceremonial centre whose hilltop triple-walled building is now interpreted as a Fortified Temple, set beside the Thirteen Towers solar observatory, plazas and buildings (BBC, The Guardian, Wikipedia); a temple complex fits that ceremonial and astronomical whole better than the older reading as a fortress alone.", "value_page": null}]'::jsonb),
    ('322cd09d-45f7-4cea-aaac-d1d973910935'::uuid, 'geom', 'SRID=4326;POINT(10.229139 60.102694)', '0101000020E61000007C36CAA4497E25400BA8582500F54D40', 'fields-wd1-2026-09-26b-s002-rollback:322cd09d-45f7-4cea-aaac-d1d973910935:geom', 'rollback of fields-wd1-2026-09-26b-s002: geom ''0101000020E61000007C36CAA4497E25400BA8582500F54D40'' restored on Svingerud Runestone', '[{"source": "https://www.wikidata.org/wiki/Q116233388", "url": "https://www.wikidata.org/wiki/Q116233388", "quote": "60°6''9.7\"N, 10°13''44.9\"E", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=59438", "url": "https://www.megalithic.co.uk/article.php?sid=59438", "quote": "Latitude: 60.103615N Longitude: 10.229997E", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0102)", "decision": "replace", "status": "CONFLICT", "reasoning": "The runestone was found in the Svingerud grave field in Hole, near Tyrifjorden. Wikidata and the Megalithic Portal both put that find site at about 60.103 N, 10.230 E. The stored point is 35.6 km away in central Oslo, where the Museum of Cultural History that keeps the stone stands; that is the museum, not the site.", "value_page": null}]'::jsonb),
