    ('32e69e53-2a3c-4e9b-9622-5606d0ddefbc'::uuid, 'site_type', 'Fortification', 'Fortress/citadel', 'fields-wd1-2026-09-26b-s002-rollback:32e69e53-2a3c-4e9b-9622-5606d0ddefbc:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Fortress/citadel'' restored on Ipf Mountain', '[{"source": "https://en.wikipedia.org/wiki/Ipf_(mountain)", "url": "https://en.wikipedia.org/wiki/Ipf_(mountain)", "quote": "The summit was already levelled, fortified and densely settled in the Urnfield period.", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Ipf_(mountain)", "url": "https://en.wikipedia.org/wiki/Ipf_(mountain)", "quote": "Mount Ipf in southern Germany. The fortification, spatial organization and territory of a “Princely Seat” of the Early Iron Age", "outcome": "found"}, {"source": "https://lgrbwissen.lgrb-bw.de/geotourismus/ausgewaehlte-aussichtspunkte/schwaebische-alb/ipf-bei-bopfingen", "url": "https://lgrbwissen.lgrb-bw.de/geotourismus/ausgewaehlte-aussichtspunkte/schwaebische-alb/ipf-bei-bopfingen", "quote": "Im Vordergrund der Grabenwall der vorgeschichtlichen Befestigungsanlage auf der Ostseite des Ipf.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0058)", "decision": "replace", "status": "CONFLICT", "reasoning": "The sources describe a prehistoric hill fort: a summit plateau ringed by walls, ditches and ramparts on the slopes (Befestigungsanlage), not a fortress or citadel. Fortification is the type that holds what they say.", "value_page": null}]'::jsonb),
