    ('336a2e13-3348-4c15-a0cb-b5523ac32913'::uuid, 'period_start', '1', '-500', 'fields-wd1-2026-09-26b-s002-rollback:336a2e13-3348-4c15-a0cb-b5523ac32913:period_start', 'rollback of fields-wd1-2026-09-26b-s002: period_start ''-500'' restored on Margus - City', '[{"source": "https://www.epa.oszk.hu/01600/01614/00021/pdf/EPA01614_jame_2013_467-483.pdf", "url": "https://www.epa.oszk.hu/01600/01614/00021/pdf/EPA01614_jame_2013_467-483.pdf", "quote": "The Roman town of Margum was founded in the 1st century AD at the place of an Iron Age settlement", "outcome": "found"}, {"source": "https://sr.wikipedia.org/wiki/%D0%9C%D0%B0%D1%80%D0%B3%D1%83%D0%BC", "url": "https://sr.wikipedia.org/wiki/%D0%9C%D0%B0%D1%80%D0%B3%D1%83%D0%BC", "quote": "Већ крајем 1. века у Маргуму је подигнут војни логор", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "replace", "status": "MISSING", "reasoning": "Bugarski and Ivanisevic state the Roman town of Margum was founded in the 1st century AD, and Serbian Wikipedia has its military camp built by the end of the 1st century; the city''s start is therefore the 1st century AD (1), not the stored -500 bucket.", "value_page": null}]'::jsonb),
    ('336a2e13-3348-4c15-a0cb-b5523ac32913'::uuid, 'source_url', 'https://en.wikipedia.org/wiki/Margum_(city)', 'https://en.wikipedia.org/wiki/Margus_(city)', 'fields-wd1-2026-09-26b-s002-rollback:336a2e13-3348-4c15-a0cb-b5523ac32913:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Margus_(city)'' restored on Margus - City', '[{"source": "https://en.wikipedia.org/wiki/Margum_(city)", "url": "https://en.wikipedia.org/wiki/Margum_(city)", "quote": "In 435, the city of Margus, under the Eastern Roman Empire", "outcome": "found"}, {"source": "https://www.epa.oszk.hu/01600/01614/00021/pdf/EPA01614_jame_2013_467-483.pdf", "url": "https://www.epa.oszk.hu/01600/01614/00021/pdf/EPA01614_jame_2013_467-483.pdf", "quote": "The Roman town of Margum was founded in the 1st century AD at the place of an Iron Age settlement", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0126)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored URL Margus_(city) is a redirect; the article itself is Margum (city), about this Roman city at Dubravica, which the independent Bugarski/Ivanisevic paper also names.", "value_page": {"lang": "en", "problem": null, "resolved_title": "Margum (city)", "unreadable": false, "wikibase_item": "Q6760837"}}]'::jsonb),
    ('33d2d754-e50a-4305-beff-87d2ad2c0227'::uuid, 'source_url', 'https://fi.wikipedia.org/wiki/Thasos_(antiikin_kaupunki)', 'https://en.wikipedia.org/wiki/Thasos', 'fields-wd1-2026-09-26b-s002-rollback:33d2d754-e50a-4305-beff-87d2ad2c0227:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Thasos'' restored on Archaeological Site of Ancient Thasos', '[{"source": "https://fi.wikipedia.org/wiki/Thasos_(antiikin_kaupunki)", "url": "https://fi.wikipedia.org/wiki/Thasos_(antiikin_kaupunki)", "quote": "Thasos (antiikin kaupunki)", "outcome": "found"}, {"source": "https://topostext.org/place/408247PTha", "url": "https://topostext.org/place/408247PTha", "quote": "Thasos, island polis, the modern Thasos town, Macedonia", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0061)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English article states it is about the island; the Finnish Wikipedia article ''Thasos (antiikin kaupunki)'' is about the ancient city itself and its archaeological sites in the east of modern Thasos town (Limenas), and ToposText independently names the same ancient polis at the modern town.", "value_page": {"lang": "fi", "problem": null, "resolved_title": "Thasos (antiikin kaupunki)", "unreadable": false, "wikibase_item": "Q21083662"}}]'::jsonb),
    ('34272ded-e2dd-47ab-b771-f3fc4a68b1bb'::uuid, 'source_url', 'https://www.turismoamelia.it/it/esplora-amelia/le-mura-poligonali/', 'https://en.wikipedia.org/wiki/Amelia,_Umbria', 'fields-wd1-2026-09-26b-s002-rollback:34272ded-e2dd-47ab-b771-f3fc4a68b1bb:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://en.wikipedia.org/wiki/Amelia,_Umbria'' restored on Polygonal Walls (Mura Poligonali)', '[{"source": "https://www.turismoamelia.it/it/esplora-amelia/le-mura-poligonali/", "url": "https://www.turismoamelia.it/it/esplora-amelia/le-mura-poligonali/", "quote": "Brani delle mura poligonali in calcare sono incorporati nelle cantine di palazzi, nei muri di recinzione di orti, alla base di edifici.", "outcome": "found"}, {"source": "https://www.umbriatourism.it/en/w/walls-of-amelia", "url": "https://www.umbriatourism.it/en/w/walls-of-amelia", "quote": "Amelia’s polygonal walls were built on the town’s previous defensive layout.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0087)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored English Wikipedia article is about the town of Amelia and the walls have no Wikipedia article; the Comune di Amelia''s tourism page ''Mura Poligonali'' is about the polygonal walls themselves, which Umbriatourism also describes.", "value_page": {"lang": null, "problem": null, "resolved_title": null, "unreadable": false, "wikibase_item": null}}]'::jsonb),
    ('348770cd-a3a2-4b6e-83f7-bd5f5d699022'::uuid, 'site_type', 'Cairn', 'Monument', 'fields-wd1-2026-09-26b-s002-rollback:348770cd-a3a2-4b6e-83f7-bd5f5d699022:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Monument'' restored on Barnenez', '[{"source": "https://www.barnenez.fr/en/", "url": "https://www.barnenez.fr/en/", "quote": "In Finistère, discover the Barnenez cairn, the largest megalithic mausoleum in Europe.", "outcome": "found"}, {"source": "https://www.megalithic.co.uk/article.php?sid=10394", "url": "https://www.megalithic.co.uk/article.php?sid=10394", "quote": "Type: Chambered Cairn", "outcome": "found"}, {"source": "https://en.wikipedia.org/wiki/Barnenez", "url": "https://en.wikipedia.org/wiki/Barnenez", "quote": "Today, the Barnenez cairn is 72 m long, up to 25 m wide, and over 8 m high.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0051)", "decision": "replace", "status": "CONFLICT", "reasoning": "The monument''s managing body (CMN), the Megalithic Portal and Wikipedia all describe Barnenez as a (chambered) cairn - a dry-stone mound covering 11 passage-grave chambers; ''Cairn'' is more specific than the generic ''Monument''.", "value_page": null}]'::jsonb),
