    ('351a3b2e-3492-4b92-adf0-700269fb06c7'::uuid, 'site_type', 'Village', 'Megalithic structures', 'fields-wd1-2026-09-26b-s002-rollback:351a3b2e-3492-4b92-adf0-700269fb06c7:site_type', 'rollback of fields-wd1-2026-09-26b-s002: site_type ''Megalithic structures'' restored on Torralba d''en Salort', '[{"source": "https://www.illesbalears.travel/en/menorca/archaeological-site-torralba-den-salort", "url": "https://www.illesbalears.travel/en/menorca/archaeological-site-torralba-den-salort", "quote": "The talayotic village of Torralba d''en Salort is made up of two talayots, a hypostyle room, the remains of dwellings and an area with a taula, its most noteworthy element.", "outcome": "found"}, {"source": "https://menorcatalayotica.info/en/Talayotic_settlement_of_Torralba_den_Salort/10670", "url": "https://menorcatalayotica.info/en/Talayotic_settlement_of_Torralba_den_Salort/10670", "quote": "Two artificial funerary caves can also be seen on our visit, as well as the remains of an outer wall and Talayotic dwellings, covered by vegetation, mounds of rubble and sediment.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0134)", "decision": "replace", "status": "MISSING", "reasoning": "The Balearic tourism board describes Torralba d''en Salort as a talayotic village of talayots, a hypostyle room and dwellings around a taula sanctuary, and Menorca Talaiòtica describes the talayotic settlement with its dwellings and outer wall; the site is a prehistoric village, which is more specific than the generic Megalithic structures.", "value_page": null}]'::jsonb),
    ('351a3b2e-3492-4b92-adf0-700269fb06c7'::uuid, 'source_url', 'https://ca.wikipedia.org/wiki/Poblat_talai%C3%B2tic_de_Torralba_d%27en_Salort', 'https://www.illesbalears.travel/tourist-resource/en/menorca/archaeological-site-torralba-den-salort', 'fields-wd1-2026-09-26b-s002-rollback:351a3b2e-3492-4b92-adf0-700269fb06c7:source_url', 'rollback of fields-wd1-2026-09-26b-s002: source_url ''https://www.illesbalears.travel/tourist-resource/en/menorca/archaeological-site-torralba-den-salort'' restored on Torralba d''en Salort', '[{"source": "https://ca.wikipedia.org/wiki/Poblat_talai%C3%B2tic_de_Torralba_d%27en_Salort", "url": "https://ca.wikipedia.org/wiki/Poblat_talai%C3%B2tic_de_Torralba_d%27en_Salort", "quote": "El poblat talaiòtic de Torralba d''en Salort és un jaciment arqueològic talaiòtic situat al sud de l''illa de Menorca, a la carretera entre Alaior i Cala en Porter.", "outcome": "found"}, {"source": "https://www.illesbalears.travel/en/menorca/archaeological-site-torralba-den-salort", "url": "https://www.illesbalears.travel/en/menorca/archaeological-site-torralba-den-salort", "quote": "The village of Torralba d''en Salort is home to the most spectacular taula on the island of Minorca, slender in proportion and painstaking in its craftsmanship.", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0134)", "decision": "replace", "status": "CONFLICT", "reasoning": "The stored tourism URL is a redirect; the site has no English Wikipedia article, so its own article in Catalan, the local language (the eswiki/cawiki sitelinks of Q2444476), is preferred, and the Balearic tourism page confirms the same site.", "value_page": {"lang": "ca", "problem": null, "resolved_title": "Poblat talaiòtic de Torralba d''en Salort", "unreadable": false, "wikibase_item": "Q2444476"}}]'::jsonb);
